window.QB_PAPERS=window.QB_PAPERS||{};window.QB_PAPERS["p25bd314b90"]={"id":"p25bd314b90","name":"2025年云南省公务员录用考试《行测》题（网友回忆版）","year":2025,"region":"云南","count":109,"types":{"马克思主义":2,"新思想":4,"时事政治":4,"法律常识":1,"人文常识":5,"科技常识":4,"逻辑填空":14,"片段阅读":11,"语句表达":4,"数学运算":10,"图形推理":7,"定义判断":8,"类比推理":10,"逻辑判断":10,"综合":5,"增长":6,"比重":2,"平均数":2},"modules":["政治理论","常识判断","言语理解与表达","数量关系","判断推理","资料分析"],"moduleCounts":{"政治理论":10,"常识判断":10,"言语理解与表达":29,"数量关系":10,"判断推理":35,"资料分析":15},"coverage":{"basis":"网友回忆版","sourceCount":109,"expectedCount":null,"missingCount":null},"questions":[{"qid":"13504351","no":1,"type":"马克思主义","module":"政治理论","stem":"<p>习近平总书记指出，“两个结合”是我们取得成功的最大法宝。关于“两个结合”，下列表述正确的有几项？<br>①“两个结合”筑牢了道路根基，中国特色的关键就在于“两个结合”<br>②“两个结合”本身就是创新，同时又开启了广阔的理论和实践创新空间<br>③“两个结合”产生了深刻的“化学反应”，造就了一个有机统一的新的文化生命体<br>④“两个结合”是坚持把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合</p>","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"D","multi":false,"explanation":"<p>本题考查理论与政策。<br>2023年6月2日，中共中央总书记、国家主席、中央军委主席习近平在北京出席文化传承发展座谈会并发表重要讲话。<br>①正确，讲话在“二、深刻理解‘两个结合’的重大意义”部分指出，第三，“结合”筑牢了道路根基。中国特色的关键就在于“两个结合”。“第二个结合”让中国特色社会主义道路有了更加宏阔深远的历史纵深，拓展了中国特色社会主义道路的文化根基。<br>②正确，讲话在“二、深刻理解‘两个结合’的重大意义”部分指出，第四，“结合”打开了创新空间。“结合”本身就是创新，同时又开启了广阔的理论和实践创新空间。“第二个结合”让我们掌握了思想和文化主动，并有力地作用于道路、理论和制度。<br>③正确，讲话在“二、深刻理解‘两个结合’的重大意义”部分指出，第二，“结合”的结果是互相成就。“结合”不是“拼盘”，不是简单的“物理反应”，而是深刻的“化学反应”，造就了一个有机统一的新的文化生命体。<br>④正确，讲话在“二、深刻理解‘两个结合’的重大意义”部分指出，在五千多年中华文明深厚基础上开辟和发展中国特色社会主义，把马克思主义基本原理同中国具体实际、同中华优秀传统文化相结合是必由之路。这是我们在探索中国特色社会主义道路中得出的规律性认识。<br>故正确的有①②③④，共4项。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":0,"pid":"p25bd314b90"},{"qid":"13504354","no":2,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，铸牢中华民族共同体意识，推进新时代党的民族工作高质量发展。关于推进新时代党的民族工作高质量发展，下列说法正确的是：<br>①把改善民生、凝聚人心作为民族地区经济社会发展的出发点和落脚点<br>②构建块状集中式社会结构和社区环境，积极促进各民族交往交流交融<br>③中国共产党领导和社会主义制度是我国各民族共同发展进步的可靠保障<br>④铸牢中华民族共同体意识、推进新时代党的民族工作高质量发展，是全党全国各族人民的共同任务</p>","options":[{"k":"A","t":"①③④"},{"k":"B","t":"①②④"},{"k":"C","t":"①②③"},{"k":"D","t":"②③④"}],"answer":"A","multi":false,"explanation":"<p>本题考查理论与政策。<br>①正确，习近平总书记在中央第七次西藏工作座谈会上强调：“必须把改善民生、凝聚人心作为经济社会发展的出发点和落脚点。”党的民族工作始终强调以人民为中心的发展思想，改善民生、凝聚人心是民族地区经济社会发展的核心目标。通过提升民族地区的生活水平和社会福利，可以增强各族人民的幸福感和归属感，促进民族团结。<br>②错误，习近平总书记在全国民族团结进步表彰大会上强调：“构建互嵌式社会结构和社区环境，不断拓宽各民族全方位嵌入的实践路径，促进各民族像石榴籽一样紧紧抱在一起。”构建互嵌式社会结构和社区环境，是促进各民族广泛交往、全面交流、深度交融，铸牢中华民族共同体意识的重要途径。因此“块状集中式社会结构和社区环境”表述错误。<br>③正确，2024年2月《求是》杂志发表习近平的重要文章《铸牢中华民族共同体意识 推进新时代党的民族工作高质量发展》中指出：“创新涉民族宣传的传播方式，丰富传播内容，拓宽传播渠道，讲好中华民族共同体故事，讲清楚中国共产党领导和社会主义制度是我国各民族共同发展进步的可靠保障，讲清楚中华民族是具有强大认同度和凝聚力的命运共同体，讲清楚中国特色解决民族问题的正确道路所具有的明显优越性。”<br>④正确，习近平总书记在二十届中央政治局第九次集体学习时讲话指出：“铸牢中华民族共同体意识、推进新时代党的民族工作高质量发展，是全党全国各族人民的共同任务。各级党委和政府要坚持中国特色解决民族问题的正确道路，认真贯彻落实党的民族工作的各项方针政策，及时研究解决本地区本单位涉及民族工作的重大问题。”<br>故说法正确的是①③④。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":1,"pid":"p25bd314b90"},{"qid":"13504353","no":3,"type":"新思想","module":"政治理论","stem":"<p>2024年习近平总书记在福建省东山县考察期间参观谷文昌纪念馆时指出，“先祭谷公、后拜祖宗”，这是老百姓发自内心的敬仰。人民心里有一本账，金杯银杯不如老百姓的口碑。这体现了：<br>①让群众满意是我们党做好一切工作的价值取向和根本标准<br>②人民是党的工作的最高裁决者和最终评判者<br>③中国共产党把为民办事、为民造福作为最重要的政绩<br>④全心全意为人民服务是党的根本宗旨</p>","options":[{"k":"A","t":"①②"},{"k":"B","t":"①②③"},{"k":"C","t":"②③④"},{"k":"D","t":"①②③④"}],"answer":"D","multi":false,"explanation":"<p>本题考查理论与政策。<br>“人民心里有一本账，金杯银杯不如老百姓的口碑”体现了“人民”是党带领人民取得非凡成就的逻辑起点，也是历史变革的价值旨归。<br>①正确，习近平总书记曾在党的群众路线教育实践活动总结大会上的讲话中指出：“让群众满意是我们党做好一切工作的价值取向和根本标准，群众意见是一把最好的尺子。”<br>②正确，2023年求是网发布的《党员干部要走好新时代党的群众路线》文章指出：习近平总书记强调，“人民是我们党的工作的最高裁决者和最终评判者”，“坚持群众路线，就要真正让人民来评判我们的工作”。衡量工作优劣要把人民群众的意见作为“标尺”，考核评价干部要把群众认不认可作为根本依据，始终把干部至于群众监督之下。<br>③正确，2020年全国两会召开前夕，习近平总书记视察山西时强调，中国共产党把为民办事、为民造福作为最重要的政绩，把为老百姓做了多少好事实事作为检验政绩的重要标准。<br>④正确，习近平总书记在庆祝改革开放40周年大会上的讲话中指出：“我们党来自人民、扎根人民、造福人民，全心全意为人民服务是党的根本宗旨，必须以最广大人民根本利益为我们一切工作的根本出发点和落脚点，坚持把人民拥护不拥护、赞成不赞成、高兴不高兴作为制定政策的依据，顺应民心、尊重民意、关注民情、致力民生。”<br>故正确的有①②③④。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":2,"pid":"p25bd314b90"},{"qid":"13504329","no":4,"type":"时事政治","module":"政治理论","stem":"<p>党的二十大报告指出，构建全国统一大市场，深化要素市场化改革，建设高标准市场体系。关于构建全国统一大市场，下列与之相关说法错误的是：</p>","options":[{"k":"A","t":"推动市场基础制度规则统一"},{"k":"B","t":"加强公平竞争审查柔性约束"},{"k":"C","t":"规范地方招商引资法规制度"},{"k":"D","t":"深化地方标准管理制度改革"}],"answer":"B","multi":false,"explanation":"<p>本题考查理论与政策。<br>B项错误，A、C、D三项正确，《中共中央关于进一步全面深化改革 推进中国式现代化的决定》在“二、构建高水平社会主义市场经济体制”部分“（6）构建全国统一大市场”中指出：“推动市场基础制度规则统一、市场监管公平统一、市场设施高标准联通。加强公平竞争审查刚性约束，强化反垄断和反不正当竞争，清理和废除妨碍全国统一市场和公平竞争的各种规定和做法。规范地方招商引资法规制度，严禁违法违规给予政策优惠行为。建立健全统一规范、信息共享的招标投标和政府、事业单位、国有企业采购等公共资源交易平台体系，实现项目全流程公开管理。提升市场综合监管能力和水平。健全国家标准体系，深化地方标准管理制度改革。”故B项中“柔性约束”说法错误。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":3,"pid":"p25bd314b90"},{"qid":"13504371","no":5,"type":"时事政治","module":"政治理论","stem":"<p>加强普惠性、基础性、兜底性民生建设，解决好人民群众最关心最直接最现实的利益问题，才能不断满足人民对美好生活的向往。关于加强普惠性、基础性、兜底性民生建设，下列表述正确的有几项？<br>①出台完善青年创新人才发现、选拔、培养机制<br>②加强低收入人口动态监测，做好分层分类社会救助工作<br>③出台政策鼓励收养病残孤儿，政府为收养家庭提供适度补贴<br>④发展集中管理运营的社区养老服务网络，提升农村互助养老设施建设水平</p>","options":[{"k":"A","t":"4项"},{"k":"B","t":"3项"},{"k":"C","t":"2项"},{"k":"D","t":"1项"}],"answer":"B","multi":false,"explanation":"<p>本题考查理论与政策。<br>2024年7月18日，中国共产党第二十届中央委员会第三次全体会议通过《中共中央关于进一步全面深化改革 推进中国式现代化的决定》（以下简称《决定》）。<br>①错误，《决定》在“四、构建支持全面创新体制机制”部分“（15）深化人才发展体制机制改革”中指出：“实施更加积极、更加开放、更加有效的人才政策······完善青年创新人才发现、选拔、培养机制，更好保障青年科技人员待遇。健全保障科研人员专心科研制度。”该举措不属于民生建设。<br>②正确，《关于加强低收入人口动态监测做好分层分类社会救助工作的意见》中指出：“社会救助是社会保障体系中兜底性、基础性的制度安排。为健全分层分类的社会救助体系，加大低收入人口救助帮扶力度，进一步织密扎牢民生兜底保障安全网，现就加强低收入人口动态监测、做好分层分类社会救助工作提出以下意见。”<br>③正确，《关于进一步促进残疾孤儿回归家庭的通知》中指出：“三、延续享受救助政策。残疾孤儿被收养后，可继续纳入‘孤儿医疗康复明天计划’项目资助范围。符合条件的，也可按规定享受社会救助或残疾人保障相关待遇，但应做好各项政策衔接，避免重复享受······六、加强政策宣传引导。各地要充分利用报纸、电台、网络等媒体，积极开展鼓励收养残疾孤儿政策宣传工作。”<br>④正确，《决定》在“十一、健全保障和改善民生制度体系”部分“（46）健全人口发展支持和服务体系”中指出：“积极应对人口老龄化······优化基本养老服务供给，培育社区养老服务机构，健全公办养老机构运营机制，鼓励和引导企业等社会力量积极参与，推进互助性养老服务，促进医养结合。”<br>故②③④表述正确，共3项。<br>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":4,"pid":"p25bd314b90"},{"qid":"13504328","no":6,"type":"时事政治","module":"政治理论","stem":"<p>党的二十届三中全会指出，法治是中国式现代化的重要保障。下列不属于完善中国特色社会主义法治体系举措的是：</p>","options":[{"k":"A","t":"健全基层民主制度"},{"k":"B","t":"深入推进依法行政"},{"k":"C","t":"深化立法领域改革"},{"k":"D","t":"加强涉外法治建设"}],"answer":"A","multi":false,"explanation":"<p>本题考查理论与政策。<br>A项错误，中国共产党第二十届中央委员会第三次全体会议提出，发展全过程人民民主是中国式现代化的本质要求。必须坚定不移走中国特色社会主义政治发展道路，坚持和完善我国根本政治制度、基本政治制度、重要政治制度，丰富各层级民主形式，把人民当家作主具体、现实体现到国家政治生活和社会生活各方面。要加强人民当家作主制度建设，健全协商民主机制，健全基层民主制度，完善大统战工作格局。<br>B、C、D三项正确，中国共产党第二十届中央委员会第三次全体会议提出，法治是中国式现代化的重要保障。必须全面贯彻实施宪法，维护宪法权威，协同推进立法、执法、司法、守法各环节改革，健全法律面前人人平等保障机制，弘扬社会主义法治精神，维护社会公平正义，全面推进国家各方面工作法治化。要深化立法领域改革，深入推进依法行政，健全公正执法司法体制机制，完善推进法治社会建设机制，加强涉外法治建设。<br>本题为选非题，故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":5,"pid":"p25bd314b90"},{"qid":"13504290","no":7,"type":"马克思主义","module":"政治理论","stem":"<p>发展新质生产力，必须进一步全面深化改革，形成与之相适应的新型生产关系。要深化经济体制、科技体制等改革，着力打通束缚新质生产力发展的堵点卡点，建立高标准市场体系，创新生产要素配置方式，让各类先进优质生产要素向发展新质生产力顺畅流动，这最直接体现了马克思主义的哪些基本观点？<br>①生产关系必须与生产力发展要求相适应，才能促进生产力发展<br>②经济基础的变更必然引起上层建筑的变革，并决定其变革方向<br>③生产关系对生产力发展具有决定作用<br>④改革是社会主义社会发展的直接动力</p>","options":[{"k":"A","t":"①②"},{"k":"B","t":"①④"},{"k":"C","t":"②③"},{"k":"D","t":"②④"}],"answer":"B","multi":false,"explanation":"<p>本题考查马克思主义。<br>①正确，生产力和生产关系的相互作用构成了生产方式的矛盾运动，这一矛盾运动中，贯穿着生产关系一定要适应生产力发展状况的规律，这条规律是不以人的意志为转移的客观规律，是历史发展的根本规律。新质生产力作为生产力的新发展形态，需要与之相适应的新型生产关系。题干中“形成与之相适应的新型生产关系。要深化经济体制、科技体制等改革，着力打通束缚新质生产力发展的堵点卡点”体现了这一观点。<br>②错误，经济基础的性质决定上层建筑的性质，有什么样的经济基础就有什么样的上层建筑。经济基础的变更必然引起上层建筑的变革，并决定其变革的方向。选项表述正确，但题干中主要强调的是生产关系与生产力的关系以及改革对生产力发展的作用，并未涉及经济基础变更引起上层建筑变革的相关内容。<br>③错误，生产力决定生产关系，生产力的产生、性质、水平和发展要求决定生产关系的产生、性质和状况等。生产关系对生产力具有反作用，生产关系适合生产力发展要求，就会推动社会生产力的发展，当生产关系不适合生产力发展的要求时，它就会阻碍生产力的发展。故“生产关系对生产力发展具有决定作用”的说法错误。<br>④正确，恩格斯指出：“所谓‘社会主义社会’不是一种一成不变的东西，而应当和任何其他社会制度一样，把它看成是经常变化和改革的社会。”题干中“深化经济体制、科技体制等改革，着力打通束缚新质生产力发展的堵点卡点”体现了通过改革来推动新质生产力的发展，进而推动社会主义社会的发展。<br>故①④说法正确。<br>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":6,"pid":"p25bd314b90"},{"qid":"13504287","no":8,"type":"时事政治","module":"政治理论","stem":"<p>2024年12月，中央农村工作会议在北京召开，会议对如何做好“三农”工作进行了具体部署，下列与之相关说法错误的是：</p>","options":[{"k":"A","t":"加强新时代农村精神文明建设，积极开展移风易俗"},{"k":"B","t":"提高农村基本公共服务水平，持续改善农村人居环境"},{"k":"C","t":"推进农业科技力量协同攻关，因地制宜发展农业新质生产力"},{"k":"D","t":"完善农产品贸易与生产协调机制，推动粮食等农产品价格稳步提升"}],"answer":"D","multi":false,"explanation":"<p>本题考查理论与政策。<br>D项错误，A、B、C三项正确，2024年中央农村工作会议强调，要聚焦学习运用“千万工程”经验、推进乡村全面振兴······推进农业科技力量协同攻关，加快科技成果大面积推广应用，因地制宜发展农业新质生产力······完善农产品贸易与生产协调机制，推动粮食等重要农产品价格保持在合理水平······推动基础设施向农村延伸，提高农村基本公共服务水平，持续改善农村人居环境，加强农村生态环境治理······实施文明乡风建设工程，加强新时代农村精神文明建设，积极开展移风易俗。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":7,"pid":"p25bd314b90"},{"qid":"13504370","no":9,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，现代化产业体系是现代化国家的物质技术基础，必须把发展经济的着力点放在实体经济上，为实现第二个百年奋斗目标提供坚强物质支撑。下列与之相关说法正确的有几项？<br>①推进实施绿色发展战略，充分发挥绿色化赋能实体经济发展效应<br>②促进数字技术和实体经济深度融合，催生新产业新业态新模式替代传统产业<br>③重视现代服务业的发展，推动现代服务业与先进制造业、现代农业深度融合<br>④推动重点产业在国内外有序转移、促进国内外产业深度融合与实体经济发展相结合</p>","options":[{"k":"A","t":"1"},{"k":"B","t":"2"},{"k":"C","t":"3"},{"k":"D","t":"4"}],"answer":"C","multi":false,"explanation":"<p>本题考查理论与政策。<br>①正确，《新型工业化是发展新质生产力的主阵地》中指出，习近平总书记强调：“要充分认识形成绿色发展方式和生活方式的重要性、紧迫性、艰巨性。”······因此，要推动绿色发展与实体经济发展相融合，充分发挥绿色化赋能实体经济发展效应。<br>②错误，《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》中指出，促进数字技术与实体经济深度融合，赋能传统产业转型升级，催生新产业新业态新模式，壮大经济发展新引擎。<br>③正确，《中华人民共和国国民经济和社会发展第十四个五年规划和2035年远景目标纲要》中指出，重视现代服务业的发展，推动现代服务业与先进制造业、现代农业深度融合，深化业务关联、链条延伸、技术渗透，支持智能制造系统解决方案、流程再造等新型专业化服务机构发展。培育具有国际竞争力的服务企业。<br>④正确，习近平总书记在二十届中央政治局第二次集体学习时强调，优化生产力布局，推动重点产业在国内外有序转移，支持企业深度参与全球产业分工和合作，促进内外产业深度融合，打造自主可控、安全可靠、竞争力强的现代化产业体系。这要求我们发挥好超大规模市场优势和超大纵深空间优势，加快建设以实体经济为支撑的现代化产业体系，引导产业合理有序梯度转移。<br>故①③④表述正确，共3项。<br>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":8,"pid":"p25bd314b90"},{"qid":"13504357","no":10,"type":"新思想","module":"政治理论","stem":"<p>习近平总书记强调，要始终保持反腐败永远在路上的坚韧执着，保持战略定力和高压态势，一步不停歇、半步不退让，一体推进不敢腐、不能腐、不想腐，坚决打好这场攻坚战、持久战、总体战。关于对当前反腐败斗争的认识，下列说法正确的有几项？<br>①加强党的纪律建设是一项经常性工作，引导党员干部把他律转化为自律<br>②新时代以来，反腐败成效有目共睹，已铲除了腐败滋生的土壤和条件<br>③不正之风是滋生腐败的温床，腐败往往是“四风”从量变转为质变的结果<br>④深化对党的自我革命的规律性认识，必须以彻底的自我革命精神把反腐败斗争进行到底<br>⑤要持续推动全面从严治党向基层延伸，让人民群众切实感受到正风肃纪反腐就在身边</p>","options":[{"k":"A","t":"2"},{"k":"B","t":"3"},{"k":"C","t":"4"},{"k":"D","t":"5"}],"answer":"C","multi":false,"explanation":"<p>本题考查理论与政策。<br>2025年1月6日，中共中央总书记、国家主席、中央军委主席习近平在中国共产党第二十届中央纪律检查委员会第四次全体会议上发表重要讲话。<br>①正确，习近平总书记在讲话中强调，加强党的纪律建设是一项经常性工作，要引导党员、干部把他律转化为自律，内化为日用而不觉的言行准则。<br>②错误，习近平总书记在讲话中强调，新时代以来，推进全面从严治党和反腐败斗争力度之大前所未有，成效有目共睹。要始终保持反腐败永远在路上的坚韧执着，保持战略定力和高压态势，一步不停歇、半步不退让，一体推进不敢腐、不能腐、不想腐，坚决打好这场攻坚战、持久战、总体战。故“已铲除了腐败滋生的土壤和条件”说法有误。<br>③正确，2025年1月，新华社发布题为《着力推动正风反腐一体深化》的文章指出，不正之风是腐败滋生的温床，腐败往往是“四风”问题由量变到质变的结果。大量案件显示，党员干部的腐化堕落往往从作风问题肇始。<br>④正确，习近平总书记关于党的自我革命的重要思想坚持马克思主义世界观和方法论，从事物矛盾中把握规律、从复杂现象中透视本质，坚持讲两点论、找平衡点，不断深化对党的自我革命的规律性认识。2024年10月28日，中央政治局召开会议审议了《关于二十届中央第三轮巡视情况的综合报告》。会议强调，要清醒认识反腐败斗争形势，纵深推进全面从严治党，以彻底的自我革命精神把反腐败斗争进行到底。<br>⑤正确，习近平总书记在讲话中指出，要持续推动全面从严治党向基层延伸。各级党委特别是市县党委要把整治群众身边不正之风和腐败问题作为重要任务常态化地抓，让老百姓可感可及。新华社发布文章指出，2024年以来，全国纪检监察机关共查处群众身边不正之风和腐败问题59.6万个、处分46.2万人，移送检察机关1.5万人，以“铁拳头”惩治“微腐败”，让人民群众切实感受到正风反腐就在身边。<br>故正确的有①③④⑤，共4项。<br>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"政治理论"},"idx":9,"pid":"p25bd314b90"},{"qid":"13504255","no":1,"type":"法律常识","module":"常识判断","stem":"<p>根据《中华人民共和国民事诉讼法》，下列说法错误的是：</p>","options":[{"k":"A","t":"调解维持收养关系的案件可以不制作调解书"},{"k":"B","t":"陪审员在执行陪审职务时，与审判员有同等的权利义务"},{"k":"C","t":"当事人王某对先予执行的裁定不服，可以申请复议一次"},{"k":"D","t":"采取对妨害民事诉讼的强制措施可以由司法行政部门决定"}],"answer":"D","multi":false,"explanation":"<p>本题考查法律常识。<br>A项正确，根据《中华人民共和国民事诉讼法》第一百零一条第一款第二项规定：“下列案件调解达成协议，人民法院可以不制作调解书：（二）调解维持收养关系的案件；”<br>B项正确，根据《中华人民共和国民事诉讼法》第四十条第三款规定：“人民陪审员在参加审判活动时，除法律另有规定外，与审判员有同等的权利义务。”<br>C项正确，根据《中华人民共和国民事诉讼法》第一百一十一条规定：“当事人对保全或者先予执行的裁定不服的，可以申请复议一次。复议期间不停止裁定的执行。”<br>D项错误，根据《中华人民共和国民事诉讼法》第一百二十条规定：“采取对妨害民事诉讼的强制措施必须由人民法院决定。任何单位和个人采取非法拘禁他人或者非法私自扣押他人财产追索债务的，应当依法追究刑事责任，或者予以拘留、罚款。”因此，采取对妨害民事诉讼的强制措施必须由人民法院决定，不可以由司法行政部门决定。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":10,"pid":"p25bd314b90"},{"qid":"13504284","no":2,"type":"人文常识","module":"常识判断","stem":"<p>关于诗句中所用典故，下列解释正确的是：</p>","options":[{"k":"A","t":"“汉帝重阿娇，贮之黄金屋”中的“汉帝”指的是汉武帝"},{"k":"B","t":"“此地别燕丹，壮士发冲冠”中的“壮士”指的是高渐离"},{"k":"C","t":"“马作的卢飞快，弓如霹雳弦惊”中的“的卢”指的是刘邦的坐骑"},{"k":"D","t":"“下马入门怀橘拜，身今却在白云边”中的“怀橘”指的是忠于帝王"}],"answer":"A","multi":false,"explanation":"<p>本题考查人文常识。<br>A项正确，“汉帝重阿娇，贮之黄金屋”出自唐代李白的《妾薄命》，意思是汉武帝宠爱阿娇时，曾说要将她贮在黄金屋里。所以这里的“汉帝”指的是汉武帝。<br>B项错误，“此地别燕丹，壮士发冲冠”出自唐代骆宾王的《于易水送人》，意思是在这个地方荆轲告别燕太子丹，荆轲悲歌壮气，怒发冲冠。所以这里的“壮士”指的是荆轲，而不是高渐离。<br>C项错误，“马作的卢飞快，弓如霹雳弦惊”出自宋代辛弃疾的《破阵子・为陈同甫赋壮词以寄之》，意思是战马像的卢马一样跑得飞快，弓箭像惊雷一样，震耳离弦。此处的“的卢”指的是三国时期刘备的坐骑，曾跳过溪水，帮助刘备摆脱追兵，而不是刘邦的坐骑。<br>D项错误，“下马入门怀橘拜，身今却在白云边”出自宋代范成大的《送詹道子教授奉祠养亲》，意思是我下马进门怀揣着橘子行礼，如今却身处白云之边‌‌。此处的“怀橘”指的是陆绩六岁时，在袁术处做客，将橘子藏在怀中，欲带回家给母亲吃的故事，体现的是对母亲的孝顺，而不是忠于帝王。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":11,"pid":"p25bd314b90"},{"qid":"13504298","no":3,"type":"人文常识","module":"常识判断","stem":"<p>下列关于汉字的表述错误的是：</p>","options":[{"k":"A","t":"甲骨文的内容多为“卜辞”"},{"k":"B","t":"“书同文”中的“文”指的是大篆"},{"k":"C","t":"“钟鸣鼎食”中的两种器具均是金文的载体"},{"k":"D","t":"隶书是篆书的化繁为简，化圆为方，化弧为直"}],"answer":"B","multi":false,"explanation":"<p>本题考查人文常识。<br>A项正确，甲骨文，主要流行于商周时期，又称“契文”、“甲骨卜辞”，是迄今为止中国发现的年代最早的成熟文字系统。因商朝的人大都迷信鬼神，大事小事都要卜问，故甲骨文的内容大部分是殷商王室占卜的记录，即“卜辞”。<br>B项错误，“书同文”是秦始皇统一六国后推行的政策，以秦国的小篆为标准，统一全国文字，这里的“文”指的是小篆，而不是大篆。<br>C项正确，“钟鸣鼎食”出自《史记·货殖列传》，钟：古代乐器；鼎：古代炊器，二者都是青铜器，而金文指的是铸造在殷商与周朝青铜器上的铭文，所以这两种器具均是金文的载体。<br>D项正确，隶书是由篆书演变而来的，它简化了篆书的结构，将篆书的圆转笔画改为方折，化繁为简，化圆为方，化弧为直。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":12,"pid":"p25bd314b90"},{"qid":"13504409","no":4,"type":"人文常识","module":"常识判断","stem":"<p>关于秦始皇陵及兵马俑坑的开疆，下列场景最不可能出现的是：</p>","options":[{"k":"A","t":"土坑内有项羽攻入关中地区后留下的焚烧痕迹"},{"k":"B","t":"坑内留下磐石、孔雀石等制作颜料的矿物"},{"k":"C","t":"兵俑中有骑兵的服饰为便于骑射的上襦下裤式"},{"k":"D","t":"兵俑上发现了工匠用来表示祖籍的“江宁”刻字"}],"answer":"D","multi":false,"explanation":"<p>本题考查人文常识。<br>A项正确，据《史记》等文献记载，项羽率领军队进入关中，烧杀抢掠，对秦朝的宫殿、陵墓等建筑进行了大规模的破坏。在兵马俑坑的考古发掘中，确实发现了一些被焚烧的痕迹，包括陶俑、坑壁等部分有被火烧过的迹象，这与史料记载相呼应，说明项羽的破坏行为极有可能是导致这些焚烧痕迹出现的原因，所以该场景是有可能出现的。<br>B项正确，秦俑的色彩丰富多样，虽然历经千年，大部分色彩已经脱落，但通过现代科学技术的分析，发现秦俑原来的彩绘颜料中含有多种矿物成分。如朱砂作红色、孔雀石制绿色，‌磐石制作白色、灰白色等。这些矿物在当时是制作颜料的常见原料，所以坑内有制作颜料矿物是可能的。<br>C项正确，战国赵武灵王推行“胡服骑射”，骑兵服饰变为上襦下裤式，方便骑射。秦承战国军事传统，骑兵服饰延续此风格，兵马俑中骑兵着上襦下裤式服饰是可能的。<br>D项错误，“江宁”是南京的旧称，最早出现于西晋。在秦朝时期，南京被称为秣陵，而非“江宁”，所以兵马俑上不可能有工匠祖籍“江宁”的刻字，该场景最不可能出现。<br>本题为选非题，故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":13,"pid":"p25bd314b90"},{"qid":"13504320","no":5,"type":"科技常识","module":"常识判断","stem":"<p>关于环境污染，下列说法正确的是：</p>","options":[{"k":"A","t":"逆温天气时，大气层变动剧烈，加快了大气污染物的扩散"},{"k":"B","t":"淡水水体大量缺氧造成藻类死亡，容易引发“赤潮”现象"},{"k":"C","t":"大气中的二氧化硫和水蒸气可被氧化合成硫酸，进而形成硫酸雾"},{"k":"D","t":"石灰粉会与油脂发生化学反应使其溶于水，可用来处理海上石油泄漏"}],"answer":"C","multi":false,"explanation":"<p>本题考查地理国情。<br>A项错误，逆温天气时，大气层出现温度随高度上升而增高的异常现象，导致空气垂直对流受阻，污染物无法扩散至高空，反而积聚在近地面，加剧污染（如雾霾）。因此，逆温天气会减缓污染物扩散，而非加快。<br>B项错误，水体富营养化指的是水体中N、P等营养盐含量过多而引起的水质污染现象。水体出现富营养化现象时，浮游藻类大量繁殖，在淡水中形成水华，这种现象在海洋中叫做赤潮或红潮。<br>C项正确，二氧化硫排放到大气中后，可被氧化为三氧化硫，再与水蒸气结合生成硫酸。硫酸与颗粒物结合形成硫酸雾（气溶胶），属于二次污染物，可导致酸雨。<br>D项错误，石灰粉是以碳酸钙为主要成分的白色粉末状物质。石灰粉与油脂一般不会发生化学反应使其溶于水。在处理海上石油泄漏时，通常以物理吸附或沉淀为主，如使用吸油材料、围油栏围控等，辅以生物降解或化学分散剂等。<br>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":14,"pid":"p25bd314b90"},{"qid":"13504299","no":6,"type":"人文常识","module":"常识判断","stem":"<p>关于急救知识，下列说法正确的是：</p>","options":[{"k":"A","t":"伤者出现呕吐时，应对其采取仰卧姿势放置，以防止窒息"},{"k":"B","t":"踝关节扭伤后，应及时采取热疗加上按摩的方式来促进血液循环"},{"k":"C","t":"冻伤后应使用温水复温，直至冻伤区域的皮肤恢复正常颜色和感觉"},{"k":"D","t":"心肺复苏需按照“胸外按压10次、人工呼吸2次”的流程循环操作"}],"answer":"C","multi":false,"explanation":"<p>本题考查科技常识。</p><p>A项错误，伤者出现呕吐时，应将其头部偏向一侧，可以使呕吐物自然流出，保持呼吸道通畅。而不是采取仰卧姿势，仰卧姿势可能会导致呕吐物堵塞气道，引起窒息。</p><p>B项错误，踝关节扭伤后，应在初期采取冷敷，而不是热疗和按摩。冷敷可以使局部血管收缩，减轻肿胀和疼痛。在扭伤初期进行热疗和按摩会加重局部出血和肿胀，不利于恢复。一般在扭伤48小时后，根据恢复情况可适当进行热疗等促进血液循环的措施。</p><p>C项正确，冻伤后使用温水复温是正确的处理方法，一般用<img src=\"assets/img/gongshi/formula-2a4425a01a7cd79c.png\" class=\"tex\">至<img src=\"assets/img/gongshi/formula-a464e5e6e5b18e18.png\" class=\"tex\">的温水浸泡冻伤部位，直至冻伤区域的皮肤恢复至正常颜色和感觉。复温过程中应避免使用过热的水或火烤等方式，以免造成二次损伤。</p><p>D项错误，心肺复苏的正确流程是胸外按压30次、人工呼吸2次，按照这样的流程循环操作，而不是胸外按压10次、人工呼吸2次。</p><p>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":15,"pid":"p25bd314b90"},{"qid":"13504257","no":7,"type":"科技常识","module":"常识判断","stem":"<p>下列与水资源有关说法错误的是：</p>","options":[{"k":"A","t":"我国主要淡水资源是冰川和地下水"},{"k":"B","t":"通过蒸发海水可以提取到氯化钠晶体"},{"k":"C","t":"利用蒸馏法淡化海水的过程主要是物理变化"},{"k":"D","t":"我国西北绝大部分地区属于地下水补给贫乏区"}],"answer":"A","multi":false,"explanation":"<p>本题考查地理国情。</p><p>A项错误，中国淡水资源总量为2.8万亿立方米，占全球水资源的6%，居世界第六位，但人均只有2200立方米，仅为世界平均水平的<img src=\"assets/img/gongshi/formula-c631bfd5fefeed63.png\" class=\"tex\">、美国的<img src=\"assets/img/gongshi/formula-361fbf4cb58d1617.png\" class=\"tex\">，是全球人均水资源贫乏的国家之一，属于缺水严重的国家。河流和湖泊是中国主要的淡水资源，河湖的分布、水量的大小，直接影响着各地人民的生活和生产。</p><p>B项正确，通过蒸发海水可以提取到氯化钠晶体，这种方法在工业上被广泛应用，称为海水晒盐。海水晒盐是利用了蒸发结晶的原理。氯化钠的溶解度随温度变化不大，通过阳光照射和风力等自然条件，使海水蒸发，溶剂减少，溶液达到饱和状态，继续蒸发，氯化钠就会以晶体的形式析出。</p><p>C项正确，蒸馏法淡化海水的原理是根据海水中各成分的沸点不同，通过加热海水使其汽化，然后将水蒸气冷却凝结成淡水。在这个过程中，只是水的状态发生了变化，从液态变为气态再变为液态，没有新物质生成，所以主要是物理变化。</p><p>D项正确，西北地区深居内陆，气候干旱少雨，降水量少，蒸发量大。地表径流缺乏，由于降水少，西北地区的河流数量少，且多为内流河，河流水量较小。一些河流在流经干旱地区时，还会因为蒸发、下渗等原因，水量逐渐减少甚至干涸。因此，河流对地下水的补给作用有限。</p><p>本题为选非题，故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":16,"pid":"p25bd314b90"},{"qid":"13504318","no":8,"type":"科技常识","module":"常识判断","stem":"<p>关于常见植物，下列说法正确的是：</p>","options":[{"k":"A","t":"香樟树抗旱耐盐碱，在北方地区更容易生长"},{"k":"B","t":"玉兰的花期在夏季，花朵有一定的药用价值"},{"k":"C","t":"银杏树现今已广泛种植，退出濒危植物名录"},{"k":"D","t":"侧柏四季常青，树形美观，常用作园林绿化"}],"answer":"D","multi":false,"explanation":"<p>本题考查科技常识。<br>A项错误，香樟树为亚热带常绿乔木，喜温暖湿润气候，耐寒性弱且不耐盐碱。北方冬季寒冷、土壤偏盐碱，不适宜其生长，故更适合南方种植。<br>B项错误，玉兰为木兰科落叶乔木，不同种类兰花的花期不同，也因不同地区的温度不同而有区别，通常在春季，而非夏季。其花可入药，有祛风散寒、宣肺通鼻之效；主要分布于安徽、江西、浙江等地，现亦广泛栽培于城市园林。<br>C项错误，银杏树虽已大规模人工种植，但野生种群仍属濒危。根据世界自然保护联盟（IUCN）《红色名录》，银杏评级为濒危（EN），尚未退出名录。<br>D项正确，侧柏为柏科常绿乔木，四季常青、树形优美，兼具耐修剪、抗污染特性，是北方园林绿化中常见的行道树、绿篱及庭院景观树种。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":17,"pid":"p25bd314b90"},{"qid":"13504260","no":9,"type":"科技常识","module":"常识判断","stem":"<p>下列关于核电站及核能的说法正确的是：</p>","options":[{"k":"A","t":"核电站的发电机能将机械能转化为电能"},{"k":"B","t":"核电站是利用核聚变产生的能量发电的"},{"k":"C","t":"核电站汽轮机中喷出的水雾体现了分子的扩散"},{"k":"D","t":"核电站产生的核废料可以同生活垃圾一起处理"}],"answer":"A","multi":false,"explanation":"<p>本题考查科技常识。<br>A项正确，核电站以核反应堆来代替火电站的锅炉，以核燃料在核反应堆中发生特殊形式的“燃烧”产生热量，使核能转变成热能来加热水产生蒸汽。蒸汽压力推动汽轮机旋转，将热能转化为机械能，然后汽轮机带动发电机旋转，发电机将机械能转化为电能。<br>B项错误，目前商业运转中的核能发电厂都是利用核裂变反应发电，而不是核聚变。因为控制核聚变的技术障碍尚未完全突破，还无法实现商业化的核聚变发电。<br>C项错误，核电站汽轮机中喷出的水雾是水蒸气遇冷液化形成的小水滴，是一种液化的物态变化现象。而分子扩散是由于分子的无规则热运动而形成的物质传递现象。因此水雾的形成并未体现分子的扩散。<br>D项错误，核电站产生的核废料具有放射性，会对环境和人类健康造成严重危害，需要进行专门的处理和处置，不能同生活垃圾一起处理。核废料通常需要经过特殊的封装、运输和长期储存等环节，以确保其放射性不会泄漏到环境中。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":18,"pid":"p25bd314b90"},{"qid":"13504258","no":10,"type":"人文常识","module":"常识判断","stem":"<p>关于少数民族特色民居，下列说法错误的是：</p>","options":[{"k":"A","t":"侗族居住的村寨一般具有依山傍水的特点"},{"k":"B","t":"蒙古包的结构简单，由木骨架和外覆的羊毛毡组成"},{"k":"C","t":"彝族民居中的炕，集床、椅子、客厅等多种功能于一身"},{"k":"D","t":"藏族碉房多用石头和土坯建造，屋顶平坦，便于晾晒粮食"}],"answer":"C","multi":false,"explanation":"<p>本题考查人文常识。<br>A项正确，侗族聚居地的村寨常沿河或山麓而建，既便于取水又利于防御。因此一般具有依山傍水的特点，通常是聚族而居，大寨三、四百户，小寨三、五十户，极少单家独户。<br>B项正确，蒙古包是草原游牧民族使用的民居形式，因大多为蒙古族使用而得名。蒙古包主要由骨架和毛毡两部分构成，结构比较简单。骨架通常是木质，毛毡通常是羊毛毡。<br>C项错误，彝族主要分布于西南地区，传统民居以火塘为核心，用于取暖、照明、烹饪等，而非“炕”。炕多见于东北汉族、满族等民族住宅，与彝族无关。<br>D项正确，碉房是中国西南部的青藏高原以及内蒙部分地区常见的居住建筑形式。为了适应青藏高原上的气候和环境，传统藏族民居大多采用石头和土坯建造，形如碉堡。碉房屋顶为平顶，草泥面用石磙压光，可供打麦、晾晒粮食及做户外活动之用。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"常识判断"},"idx":19,"pid":"p25bd314b90"},{"qid":"13504261","no":1,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>对分类学者来说，与其说是找到新物种，不如说是碰到新物种。新物种的发现往往并非<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，而是意外之喜。在阅读文献、野外调查、查阅图片或者研究标本时，分类学者偶尔会发现某份标本或者个体跟之前的记录不一样，进而通过形态学比较或者分子测序手段确认该物种是否属于新的物种。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"守株待兔"},{"k":"B","t":"刻舟求剑"},{"k":"C","t":"照本宣科"},{"k":"D","t":"按图索骥"}],"answer":"D","multi":false,"explanation":"<p>根据“并非······而是”可知，横线处所填成语与“意外之喜”构成反义并列，且根据前文“不如说是碰到新物种”以及后文“偶尔会发现某份标本或者个体跟之前的记录不一样”可知，新物种并不是通过以往的记录或文献发现的，而是偶然间发现的，故横线处所填成语需体现通过以往的资料或线索发现之意。D项“按图索骥”比喻依照线索去寻找事物，符合文意，当选。<br>A项“守株待兔”比喻死守狭隘的经验不知变通，也讽刺妄想不劳而获的侥幸心理，B项“刻舟求剑”比喻办事刻板拘泥，不知根据实际情况处理问题，均与文意不符，排除；<br>C项“照本宣科”形容讲课、发言等死板地按照课文、讲稿，没有发挥，不生动，与“新物种的发现”搭配不当，排除。<br>故正确答案为D。<br>【文段出处】《哪里更容易碰到新物种？》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":20,"pid":"p25bd314b90"},{"qid":"13504279","no":2,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>食品数字标签，相当于电子“身份证”，通过二维码等形式展示食品的标签信息，消费者可以扫描食品标签上的二维码，通过页面放大、语音识读、视频讲解等多种功能，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>地获取食品的相关信息。比如，食品的名称、配料表、生产日期和保质期、营养成分表等信息，消费者<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"持续 一览无遗"},{"k":"B","t":"实时 一清二楚"},{"k":"C","t":"详尽 一举两得"},{"k":"D","t":"便捷 一目了然"}],"answer":"D","multi":false,"explanation":"<p>第一空，根据“消费者可以扫描食品标签上的二维码”“比如，食品的名称、配料表、生产日期和保质期、营养成分表等信息”可知，文段强调通过食品数字标签，消费者获取食品相关信息非常便利，且获取的信息全面，故横线处所填词语要体现便利、全面之意，C项“详尽”指详细全面，没有遗漏，D项“便捷”指方便快捷，均符合文意，保留。A项“持续”指连续不断，与“扫码”这一动作不匹配，排除；B项“实时”指在某事发生、发展的实际时间同步做某事，与文段“比如”之后列举的内容不符，排除。<br>第二空，根据“消费者可以扫描食品标签上的二维码······获取食品的相关信息”“比如，食品的名称、配料表、生产日期和保质期、营养成分表等信息”可知，文段强调消费者对于食品相关信息清楚了解，故横线处所填成语要体现清楚之意，D项“一目了然”形容事物、事情原委很清晰，一看就知道是怎么回事，符合文意，当选。C项“一举两得”指做一件事，同时收获两方面的好处，文段未提及两方面好处，排除。<br>故正确答案为D。<br>【文段出处】红网《食品数字标签保护“舌尖上的安全”》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":21,"pid":"p25bd314b90"},{"qid":"12882019","no":3,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>通过迁地保护、建立常态化监测体系、保护和修复野生动植物赖以生存的生态家园等一系列举措，云南许多珍稀动植物的命运正在被<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。滇金丝猴数量增长到3300余只，西黑冠长臂猿、绿孔雀等20多种野生动物种群数量也大幅上升；漾濞槭、华盖木等30种极小种群野生植物<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>灭绝威胁。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"改编 挣脱"},{"k":"B","t":"改写 脱离"},{"k":"C","t":"改变 面临"},{"k":"D","t":"修改 受到"}],"answer":"B","multi":false,"explanation":"<p>第一空，搭配“命运”，根据前文可知，横线处表达一系列举措对云南许多动植物命运产生积极影响，B项“改写”指变换另一种写法，C项“改变”指使发生变化，均与“命运”搭配恰当，且符合文意，保留。A项“改编”指根据原著重新编写，D项“修改”指改正文章、计划等里面的错误、缺点，均与“命运”搭配不当，排除。<br>第二空，根据前文可知，一系列举措对云南许多珍稀动植物起到积极作用，横线处应表达不再面临灭绝威胁之意。B项“脱离”指离开（某种环境或情况），符合文意，当选。C项“面临”指面前遇到（问题、形势等），与文意相悖，排除。<br>故正确答案为B。<br>【文段出处】光明日报《解码生物多样性保护的云南经验》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":22,"pid":"p25bd314b90"},{"qid":"13504312","no":4,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>党员干部必须拧紧世界观、人生观、价值观这个“总开关”，既避免“月黑风高无人见”的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、提防“你知我知天知地知”的花言巧语，也杜绝“富贵险中求”的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>心理、纠正“法不责众”的错误认识。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"欲盖弥彰 犯罪"},{"k":"B","t":"别有用心 赌徒"},{"k":"C","t":"心怀叵测 激进"},{"k":"D","t":"自欺欺人 侥幸"}],"answer":"D","multi":false,"explanation":"<p>本题可从第二空入手，搭配“心理”，且根据“富贵险中求”可知，横线处应体现为追求富贵而敢于冒险的心理，B项“赌徒”心理指个体在面临未知与风险时，表现出过度乐观与冒险行为的倾向，常伴随着对潜在损失的轻视以及对可能收益的过度乐观估计，D项“侥幸”心理指妄图通过偶然的原因去取得成功或避免灾害，均与“心理”搭配恰当且符合文意，保留。A项“犯罪”心理指行为人形成犯罪决意并支配犯罪行为实施的各种心理因素的总和，冒险并不意味着一定犯罪，与文意不符，排除；C项“激进”心理指一种倾向于采取极端或激进的行动和观点的心理状态，侧重于强调急切与超前，与文意不符，排除。<br>第一空，根据“党员干部必须拧紧世界观、人生观、价值观这个‘总开关’”和“避免‘月黑风高无人见’”可知，横线处应体现自以为自己的行为在黑夜里无人知晓的心理，D项“自欺欺人”指自己欺骗自己，也欺骗别人，符合文意，当选。B项“别有用心”指言论或行动另有不可告人的企图，与文意不符，排除。<br>故正确答案为D。<br>【文段出处】人民日报《让清风正气不断充盈》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":23,"pid":"p25bd314b90"},{"qid":"13504375","no":5,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>发展新质生产力需要传统产业的支撑与贡献。发展好传统产业，可以稳住经济的基本盘，避免<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，为产业转型提供回旋空间，为新产业培育积累产业基础。因此，发展新质生产力不能不立先破、盲目放弃或忽视传统产业，也不能<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，盲目上马所谓的高新技术产业。<br>依次填入画横线部分最恰当的一项是:</p>","options":[{"k":"A","t":"随波逐流 人云亦云"},{"k":"B","t":"大开大合 瞎子摸象"},{"k":"C","t":"无的放矢 朝秦暮楚"},{"k":"D","t":"大起大落 一哄而上"}],"answer":"D","multi":false,"explanation":"<p>第一空，根据“发展好传统产业，可以稳住经济的基本盘，避免······”可知，横线处所填成语应与“稳住”意思相反，体现不稳定、波动大之意，D项“大起大落”指大幅度的起与落，形容变化大，可体现“不稳定”之意，符合文意，保留。A项“随波逐流”比喻自己没有立场和主见，只是随着潮流走，B项“大开大合”形容文思跌荡，放得开，收得拢，C项“无的放矢”比喻说话做事没有明确目的，或不切合实际，均与文意不符，排除。<br>第二空，代入验证。根据“盲目上马所谓的高新技术产业”可知，横线处所填成语应形容“盲目上马”这一行为，D项“一哄而上”比喻做事没有计划、没有组织，大家乱糟糟地开始上马，符合文意，当选。<br>故正确答案为D。<br>【文段出处】光明网-文摘报《全国统一大市场建设有助于处理好三对关系》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":24,"pid":"p25bd314b90"},{"qid":"13504385","no":6,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>学以致用，是知识的实用化；学以致思，是知识的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>化，是追求知识的本源，是在哲学、思维学层面认识人类知识本身。学以致思，能帮助人们更恰当地运用知识，也能帮助人们从知识的实践中总结、归纳规律性的东西，反哺学以致用。所以，自觉学以致用与学以致思两者都不能<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"具体 偏爱"},{"k":"B","t":"概括 偏颇"},{"k":"C","t":"抽象 偏废"},{"k":"D","t":"具象 偏执"}],"answer":"C","multi":false,"explanation":"<p>第一空，根据“是追求知识的本源，是在哲学、思维学层面认识人类知识本身”可知，横线处所填词语应体现出把知识理论化、深入化，从具体实践中提炼知识的本质，C项“抽象”指从许多事物中，舍弃个别的、非本质的属性，抽出共同的、本质的属性，符合文意，保留。A项“具体”指细节方面很明确的、不抽象的，与文意不符，排除；B项“概括”指总括，把事物的共同特点往一起归结，侧重于归纳总结，无法体现出从具体知识向理论化、深入化的转变。若无法确定，可在第二空继续对比。D项“具象”指具体的、不抽象的，与文意不符，排除。<br>第二空，根据“学以致思······反哺学以致用”可知，横线处所填词语应体现学以致用和学以致思两者都很重要，不能忽视任何一方，C项“偏废”指因过于重视几件事情中的某一件而忽视、荒废其它，符合文意，当选。B项“偏颇”指偏向一方，不公正，侧重不公平，与文意不符，排除。<br>故正确答案为C。<br>【文段出处】钱江晚报《术业有专攻 知识有边界》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":25,"pid":"p25bd314b90"},{"qid":"13504376","no":7,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>生活中，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的例子很多，但事与愿违的情况时有发生。譬如初涉职场的人总希望得到提拔重用，将注意力和心思用在讨好领导上；从事科研的人希望能找到捷径一举成名，等等。这些偏离航向的努力，即使偶有收获，也会<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。希望是动力，没有什么不好，但必须走在正确的路径上。<br>依次填入画横线部分最恰当的一项是:</p>","options":[{"k":"A","t":"急于求成 得不偿失"},{"k":"B","t":"循规蹈矩 贪小失大"},{"k":"C","t":"急功近利 事倍功半"},{"k":"D","t":"拔苗助长 一损俱损"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“譬如初涉职场的人总希望得到提拔重用，将注意力和心思用在讨好领导上；从事科研的人希望能找到捷径一举成名”可知，这些例子体现出人们急切想要获得成功的心态，A项“急于求成”指急着要取得成功，C项“急功近利”指急于追求眼前的成效和利益，均符合文意，保留。B项“循规蹈矩”原指遵守规矩，不敢违反，现也指拘守旧准则，不敢稍做变动，无法体现出后文表达的急切心理，排除；D项“拔苗助长”比喻违反事物发展的客观规律，急于求成，反而坏事，横线处并无“反而坏事”的含义，排除。<br>第二空，前文提到“事与愿违的情况时有发生”以及“这些偏离航向的努力”，说明即使偶有收获，但是相比付出，收获也是很少的，A项“得不偿失”意思是所得的利益抵偿不了所受的损失，符合文意，当选。C项“事倍功半”形容做事的方法费力大，收效小，强调的是方法不对导致效率低，而文段强调的是收获与付出不成正比，排除。<br>故正确答案为A。<br>【文段出处】光明网-文摘报《追马与种草》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":26,"pid":"p25bd314b90"},{"qid":"13504278","no":8,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>近年来，“打卡无人区”成为一些人的时髦选择，诸如青海可可西里、新疆罗布泊等人迹罕至的自然保护区，成了不少人<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的人间秘境。但是，“无人区”及自然生态保护区，远没有外界想象得那么浪漫和神秘。每个游客及旅行团都要深刻认识到这类地区的极端危险性，切莫仅凭一腔热血与<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，就盲目进发。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"念兹在兹 臆想"},{"k":"B","t":"念念不忘 激情"},{"k":"C","t":"心驰神往 好奇"},{"k":"D","t":"心醉神迷 勇气"}],"answer":"C","multi":false,"explanation":"<p>第一空，横线处搭配“人间秘境”，且根据“时髦选择”可知，文段表达人迹罕至的自然保护区成为很多人向往的地方，C项“心驰神往”形容思想集中在追求和向往的事情或地方上，一心向往，搭配恰当，符合文意，保留。A项“念兹在兹”指念念不忘某一件事情，与“人间秘境”搭配不当，排除；B项“念念不忘”指牢记于心，时刻不忘，搭配地点时多搭配去过的地方，文段中并没有去过，与文意不符，排除；D项“心醉神迷”形容佩服爱慕到极点，程度过重，排除。<br>第二空，代入验证，根据“每个游客及旅行团都要深刻认识到这类地区的极端危险”可知，文段表达这类地区很危险，不能盲目出发，C项“好奇”指对自己不了解的事物觉得新奇而感兴趣，能体现促使人们盲目进发的情绪，与文意相符，当选。<br>故正确答案为C。<br>【文段出处】《不得擅自进入“无人区”，青海这个提醒为何必要？|新京报快评》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":27,"pid":"p25bd314b90"},{"qid":"13504264","no":9,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>未来，金融机构应该如何进一步做好科技金融服务？ 要根据高技术产业研发投入大、周期长、风险高等特点，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>创新信贷服务模式，最大限度提高信贷服务的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，通过规范发展“贷款+外部直投”、科技保险、科技领军企业供应链金融等专属金融服务，全方位畅通高新技术企业的贷款通道。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"因势利导 适配性"},{"k":"B","t":"量身定制 特殊性"},{"k":"C","t":"兼收并蓄 积极性"},{"k":"D","t":"固本强基 重要性"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“要根据高技术产业研发投入大、周期长、风险高等特点” 可知，横线处所填成语应体现根据高技术产业的特点去创新信贷服务模式之意。A项“因势利导”指顺着事情的发展趋势加以引导，B项“量身定制”指根据功能需要定制产品，均符合文意，保留。C项“兼收并蓄”指把不同内容、不同性质的东西收下来，侧重“包容性”，D项“固本强基”指加固本体、强化基础，均与文意无关，排除。<br>第二空，搭配“信贷服务”，结合后文“通过规范发展‘贷款+外部直投’、科技保险、科技领军企业供应链金融等专属金融服务，全方位畅通高新技术企业的贷款通道”可知，横线处所填词语应体现信贷服务要与高技术产业贷款需求相匹配。A项“适配性”指互相匹配，相互适应，符合文意，当选。B项“特殊性”强调不同于一般，“最大限度提升特殊性”表述程度过重，与文意不符，排除。<br>故正确答案为A。<br>【文段出处】经济日报 《精准做好科技金融服务》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":28,"pid":"p25bd314b90"},{"qid":"13504378","no":10,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>大自然的雄性和小部分雌性动物在性竞争中会采取<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的手段，比如“控制资源”“使用武器”，以及进化出更有<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的形态或功能（表型）等。而推动雄性表型性进化的动力，是雌性作为选择者凭借其感官系统和大脑机制的结合在选择配偶的过程中表现出来的性审美。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"匪夷所思  亲和力"},{"k":"B","t":"行之有效  攻击性"},{"k":"C","t":"独出心裁  独特性"},{"k":"D","t":"多种多样  吸引力"}],"answer":"D","multi":false,"explanation":"<p>本题可从第二空入手，根据“是雌性作为选择者凭借其感官系统和大脑机制的结合在选择配偶的过程中表现出来的性审美”可知，雄性所进化出的形态或功能（表型）符合雌性审美，且能吸引雌性，故横线处所填词语需体现吸引之意，A项“亲和力”比喻使人感到融洽、亲切并愿意接近的力量，D项“吸引力”指能吸引别的事物、人或人的兴趣的性质或能力，均符合文意，保留。B项“攻击性”指具有对他人有意挑衅、侵犯或对事物有意损毁、破坏等心理倾向和行为的人格特征，C项“独特性”指某物或某人所具有的区别于其他同类事物的特性，均与文意不符，排除。<br>第一空，横线后通过“比如”对前文进行举例分析，根据“‘控制资源’‘使用武器’，以及进化出更有······的形态或功能（表型）等”可知，横线处所填成语应体现出大自然的雄性和小部分雌性动物在性竞争中会采取多种手段之意，D项“多种多样”指多方面的、五花八门，符合文意，当选。A项“匪夷所思”指事物怪异或人的言行离奇，不是一般人按照常理所能想象的，文段并无怪异、离奇之意，排除。<br>故正确答案为D。<br>【文段出处】中国科学报《它们的审美是异性进化的动力》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":29,"pid":"p25bd314b90"},{"qid":"13504314","no":11,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>在发展流变中，汉语的表达效率不断提升。比如，“枯藤老树昏鸦，小桥流水人家，古道西风瘦马”，三个短句，省去了一切连接、修饰，全由名词并列而成。高度<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的表达下，九种景物看似独立存在，实则互相<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>、有机相融，构建出一幅萧瑟秋景，游子离家、悲秋之情<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"简练 叠加 呼之欲出"},{"k":"B","t":"简约 呼应 显而易见"},{"k":"C","t":"概括 关联 不言而喻"},{"k":"D","t":"凝练 照应 溢于言表"}],"answer":"D","multi":false,"explanation":"<p>第一空，根据“省去了一切连接、修饰”可知，横线处所填词语应体现表达方式非常精炼，没有多余内容之意。A项“简练”指简明精练，B项“简约”指简略，D项“凝练”指紧凑简练，均符合文意，保留。C项“概括”指把事物的共同特点归结在一起加以简明地叙述，侧重对复杂内容进行归纳总结，与文意不符，排除。<br>第二空，根据“有机相融，构建出一幅萧瑟秋景”可知，横线处所填词语应表明景物之间彼此联系，形成一个有机的整体，B项“呼应”指互相照应，D项“照应”指对照呼应，均可体现互相存在联系，符合文意，保留。A项“叠加”指的是使预先成并存储的图形、属性特征等被调用并叠合在一个基本图形上的过程或方法，强调物理性的机械堆砌，无法体现出景物之间的内在联系，与文意不符，排除。<br>第三空，搭配“游子离家、悲秋之情”，且根据“构建出一幅萧瑟秋景，游子离家、悲秋之情”可知，横线处所填成语应体现出文字所想表达的情感非常深切之意，D项“溢于言表”意为超出言语以外，指某种思想感情虽未说明却能使人体会出来，符合文意，当选。B项“显而易见”意为事情或道理很明显，极容易看清，一般用来形容事情、道理等比较直观，容易被察觉，与“游子离家、悲秋之情”搭配不当，且“游子离家、悲秋之情”是通过对景物的描写委婉地表达出来的，并非是那种一眼就能看清楚的，置于此处不如D项更符合文意，排除。<br>故正确答案为D。<br>【文段出处】人民日报《汉语的魅力从何而来》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":30,"pid":"p25bd314b90"},{"qid":"13504283","no":12,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>武器因人类生存需要而产生，最初的武器来自自然的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。参照蚌壳边缘、石块边棱等尖锐、锋利的存在，人类学会了制作第一批原始武器。基于对弹性、惯性、杠杆原理等概念的<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>认识，人类学会了制作弓弩、抛石机等弹射武器，极大地扩展了武器的攻击<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"馈赠 粗浅 手段"},{"k":"B","t":"启发 模糊 距离"},{"k":"C","t":"效法 初步 范围"},{"k":"D","t":"模仿 清醒 强度"}],"answer":"B","multi":false,"explanation":"<p>第一空，根据“参照蚌壳边缘、石块边棱等尖锐、锋利的存在”可知，横线处所填词语应体现因为自然而学会制作武器之意，B项“启发”指用事例引起对方联想并有所了解、领悟，符合文意，保留。A项“馈赠”指赠送，文段强调人类从自然现象中主动学习制作武器，而非被动给予，与文意不符，排除；C项“效法”指仿照别人的做法去做，学习别人的长处，D项“模仿”指照某种现成的样子学着做，置于此处应表述为“对自然的效法/模仿”，用法均错误，排除。<br>第二空，代入验证，根据“人类学会了制作弓弩、抛石机等弹射武器”可知，人类处于制作弹射武器的阶段，横线处要表达人类对科学原理的认知不深入之意，B项“模糊”指不清楚、不分明，与文意相符，保留。<br>第三空，代入验证，搭配“扩展”，且根据“弓弩、抛石机等弹射武器”可知，横线处要表达出弹射武器可以攻击更远的目标，B项“距离”指事物在空间或时间上相隔，符合文意，且搭配恰当，当选。<br>故正确答案为B。<br>【文段出处】物理《古代武器中的物理学》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":31,"pid":"p25bd314b90"},{"qid":"13504280","no":13,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>面对疑难杂症，临床医学上很多时候只能摸着石头过河。在这方面，AI可以发挥很大作用。它能<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>影像、病理、基因等多模态数据，提供多尺度综合分析，帮助我们构建更<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的肿瘤画像。肿瘤是一个由复杂癌细胞组成的生态系统，对其画像勾勒得越<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>，就越能发现以往忽视的肿瘤行为和潜在治疗靶点，为前端治疗提供新思路。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"整合 完整 准确"},{"k":"B","t":"收集 稳定 详尽"},{"k":"C","t":"模拟 具象 立体"},{"k":"D","t":"回溯 精细 透彻"}],"answer":"A","multi":false,"explanation":"<p>第一空，根据“提供多尺度综合分析”可知，此处体现AI能获取多种数据，对多种数据进行处理，从而提供多尺度综合分析之意，A项“整合”指把零散的东西彼此衔接，从而实现信息系统的资源共享和协同工作，形成有价值有效率的一个整体，B项“收集”指使聚集在一起，均可体现获取或处理多种数据之意，保留。C项“模拟”指对真实事物或者过程的虚拟，侧重于模仿虚拟，D项“回溯”指上溯，向上推导，向内推导，侧重于推导，回忆，均不符获取或处理多种数据之意，排除。<br>第二空，搭配“肿瘤画像”，结合“提供多尺度综合分析”可知，此处体现构建更为全面的肿瘤画像之意，A项“完整”指具有或保持着应有的部分，没有损坏或残缺，可与“肿瘤画像“搭配，且可体现较为全面的肿瘤画像之意，保留。B项“稳定”指稳恒固定；没有变动；使稳定，与“肿瘤画像”搭配不当，且意思为稳定不变，不符合文意，排除。<br>第三空，代入A项验证，“准确”指行动的结果完全符合实际或预期，可对应后文“就越能发现以往忽视的肿瘤行为和潜在治疗靶点”，可体现对画像勾勒的正确性，当选。<br>故正确答案为A。<br>【文段出处】《AI如何助力重塑肿瘤诊疗模式》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":32,"pid":"p25bd314b90"},{"qid":"12882020","no":14,"type":"逻辑填空","module":"言语理解与表达","stem":"<p>欣赏现场古典音乐表演时，往往有以下<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的规矩：手机调成静音，安静就座，保持肃静，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>地聆听，等一首作品表演完毕才鼓掌······然而，这些看似<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>的欣赏古典音乐表演的方式只是现代社会的独有现象，在这些音乐作品诞生的那个年代，欣赏方式并非如此。<br>依次填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"一丝不苟 心无旁骛 规范"},{"k":"B","t":"郑重其事 正襟危坐 科学"},{"k":"C","t":"众所周知 目不转睛 标准"},{"k":"D","t":"约定俗成 全神贯注 正确"}],"answer":"D","multi":false,"explanation":"<p>第一空，横线处搭配“规矩”，且根据后文“手机调成静音，安静就座，保持肃静”“······欣赏古典音乐表演的方式只是现代社会的独有现象”可知，这些行为并非明文规定，而是现代社会逐渐形成的普遍认可的共同习惯。C项“众所周知”侧重于大家都知道，D项“约定俗成”指事物的名称或社会习惯往往是由人民群众经过长期社会实践而确定或形成的。二者均可和“规矩”搭配，且符合文意，保留。A项“一丝不苟”指做事认真细致，B项“郑重其事”指态度严肃认真，二者均与“规矩”搭配不当，排除。<br>第二空，横线处与“聆听”搭配，形容聆听的状态。D项“全神贯注”形容注意力高度集中，可以形容专注于音乐聆听的状态，保留。C项“目不转睛”指眼球一动不动地盯着看，形容注意力高度集中，“聆听”主要是用耳朵而非眼睛，搭配不当，排除。<br>第三空，代入验证。根据“这些看似······只是现代社会的独有现象，在这些音乐作品诞生的那个年代，欣赏方式并非如此”可知，在现代社会的认知中，“手机调成静音，安静就座，保持肃静”这些欣赏方式是符合当下的特有的礼仪规范的，被当下人们普遍认可的。D项“正确”指符合事实、道理或某种公认的标准，符合文意，当选。<br>故正确答案为D。<br>【文段出处】中国社会科学网《古典音乐表演聆听规范的历史演变》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":33,"pid":"p25bd314b90"},{"qid":"13504317","no":15,"type":"片段阅读","module":"言语理解与表达","stem":"<p>绝大部分孤独症儿童会有心理问题，如认知、情绪和行为问题。研究发现，大约46%的孤独症儿童拥有平均值或平均值以上的智商，但也有研究显示，60%的孤独症儿童伴有不同水准的智力发育落后，孤独症儿童个体差异很大，小部分表现出“孤岛智慧”，在绘画、乐器、音乐、色彩、计算、机械记忆、方位辨别等方面有特别突出的表现，如果能加以合理引导与培养转化，将对其职业开发有积极意义。<br>关于孤独症，这段文字未提及的是：</p>","options":[{"k":"A","t":"患者的临床表现"},{"k":"B","t":"患者的个体差异"},{"k":"C","t":"患者的心理问题"},{"k":"D","t":"患者的智力发育"}],"answer":"A","multi":false,"explanation":"<p>A项，“患者的临床表现”文段未提及，无中生有，当选；<br>B项，根据“孤独症儿童个体差异很大，小部分表现出‘孤岛智慧’”可知，“患者的个体差异”文段有提及，排除；<br>C项，根据“绝大部分孤独症儿童会有心理问题，如认知、情绪和行为问题”可知，“患者的心理问题”文段有提及，排除；<br>D项，根据“研究发现，大约46%的孤独症儿童拥有平均值或平均值以上的智商，但也有研究显示，60%的孤独症儿童伴有不同水准的智力发育落后”可知，“患者的智力发育”文段有提及，排除。<br>本题为选非题，故正确答案为A。<br>【文段出处】文摘报《孤独症不是心理疾病》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":34,"pid":"p25bd314b90"},{"qid":"13504362","no":16,"type":"片段阅读","module":"言语理解与表达","stem":"<p>在机场过安检时，有时会遇到这样的情景：安检人员用一张白色的小纸片在你的手提行李、电子设备，甚至你的衣服上擦拭一遍，再将试纸放入一旁的仪器中。这张白色的小纸片其实是一种专门设计的爆炸物痕量检测纸，用于探测行李或物品表面是否残留有爆炸物的痕迹。它的使用起源于对航空安全的严格要求，尤其是在现代航空业面对的恐怖主义威胁日益增多的背景下，痕量检测技术已成为机场安检系统中的重要组成部分。<br>这段文字接下来最不可能谈及的是：</p>","options":[{"k":"A","t":"爆炸物痕量检测纸的工作原理"},{"k":"B","t":"安检中使用痕量检测纸的利弊"},{"k":"C","t":"机场采用痕量检测技术的背景"},{"k":"D","t":"候机楼发现爆炸物的处置程序"}],"answer":"D","multi":false,"explanation":"<p>本题为接语选择题，需通读全文，重点把握文段最后讨论的核心话题。文段开篇描述机场安检人员使用爆炸物痕量检测纸的情景，接着介绍其用途、使用起源，最后强调痕量检测技术在机场安检系统的重要性。故文段接下来应重点围绕痕量检测技术在安检中的相关内容展开。<br>A项，文段描述了痕量检测纸的用途，但并未深入解释其工作原理，此项与文段话题紧密相关，排除；<br>B项，文段探讨了痕量检测技术的重要性，但并未提及其弊端，探讨其利弊是合理延伸，排除；<br>C项，“机场采用痕量检测技术的背景”与尾句“背景”相关，接下来有可能展开探讨，排除；<br>D项，与文段最后谈论的核心话题不符，接下来最不可能谈及，当选。<br>本题为选非题，故正确答案为D。<br>【文段出处】科普中国《坐飞机过安检时擦的小纸片是什么？》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":35,"pid":"p25bd314b90"},{"qid":"13504383","no":17,"type":"片段阅读","module":"言语理解与表达","stem":"<p>从传播史上来讲，人类的传播形式经历过人际交往的口头传播。在这个阶段，由于传播主体的时空局限，文化传播特别缓慢，其中的文化是歌乐舞一体的，人可以说是“混沌的人”。文字发明之后的书写传播，扩大了空间范围、延伸了时间长度，随之诞生了一种具有反思精神和思想反刍意味的“深度的人”。古登堡革命之后是大规模印刷时代的到来，新闻报刊与20世纪以来的广播、电影视等共同将人类带入了大众传播时代。这种传播模式下，它的受众是一种“无个性的人”。这是一个由小众到大众的发展历程，也是一种人的演变过程。<br>这段文字主要介绍了：</p>","options":[{"k":"A","t":"人类传播形式的演变历史"},{"k":"B","t":"技术进步对人类传播形式的影响"},{"k":"C","t":"人从“混沌”变为“深度”的过程"},{"k":"D","t":"人类感知世界和认识社会方式的进化"}],"answer":"D","multi":false,"explanation":"<p>文段开篇从传播史视角切入，详细阐述了人类传播形式演变对人类自身感知的影响，即口头传播时期，受时空局限，人类处于“混沌的人”；书写传播时期，因时空扩展，使人们反思和思想反刍成为可能，认知方式得以深化，成为“深度的人”；大众传播时代，人们成为“无个性的人”。尾句通过指代词“这”对前文内容进行了总结，即人类在传播形式发展过程中，自身的认知也在演变。故文段重点强调人类自身感知的演变，对应D项。<br>A项，仅提及传播形式的改变，而未提及人自身的演变，偏离文段结论的重点，排除；<br>B项，文段并非强调“技术进步的影响”，而是“人类自身感知的演变”，偏离文段重点，排除；<br>C项，从“混沌”变为“深度”，仅涉及“从口头传播到书写传播”过程中的部分内容，未包括大众传播时代这些“无个性的人”，概括的不够全面，排除。<br>故正确答案为D。<br>【文段出处】光明日报《网络生态下对文学走向的展望》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":36,"pid":"p25bd314b90"},{"qid":"13504339","no":18,"type":"片段阅读","module":"言语理解与表达","stem":"<p>水墨作为民族文化的重要象征，是历代国人观察和表现世界的一种独特方式。有别于传统绘画，当代水墨更为贴近这个时代，有着对艺术更为深入的思考。当代水墨艺术家更注重反映当下人的生存状态和精神指向，他们既了悟中国传统文化的艺术灵蕴，又深谙西方先锋艺术语言，同时兼具人文关怀和独立品格，其作品往往能够从传统中汲取精华，又能在西方美学中吸收养分，进而创造出一种新的当代语言，形成自己特有的笔墨方式来表达艺术理想，具有鲜活的时代特征和生命力量。<br>这段文字主要介绍了：</p>","options":[{"k":"A","t":"传统水墨与当代水墨之间的差异"},{"k":"B","t":"水墨作为民族文化象征的重要地位"},{"k":"C","t":"当代水墨艺术家及其作品的独特造诣"},{"k":"D","t":"水墨艺术折射出的人文关怀和文化精华"}],"answer":"C","multi":false,"explanation":"<p>文段开篇引出“水墨”的话题，接着指出“当代水墨”更贴近时代且有更深入的艺术思考。随后阐述“当代水墨艺术家”更注重反映当下人的生存状态与精神指向，他们有其自身的优势，进而强调他们的作品能从传统和西方美学中汲取养分，创造新语言、形成独特笔墨方式来表达艺术理想，具有鲜活时代特征和生命力量。故文段主题词为“当代水墨艺术家”，重点讨论当代水墨艺术家及其作品的特点，对应C项。<br>A项，“传统水墨”为引出主题词“当代水墨艺术家”的铺垫，非重点，排除；<br>B项，“水墨的重要地位”为开篇引入部分，非重点，排除；<br>D项，“水墨艺术折射出的人文关怀和文化精华”为当代水墨艺术家及其作品的具体特点，未重点突出“当代水墨艺术家”，偏离文段重点，排除。<br>故正确答案为C。<br>【文段出处】雅昌新闻《贾廷峰：当代水墨是未来艺术投资的潜力股》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":37,"pid":"p25bd314b90"},{"qid":"13504345","no":19,"type":"语句表达","module":"言语理解与表达","stem":"<p>随着天气越来越冷，早晨起床也变得越来越难，睡醒了总想赖一会儿床，有人觉得这就是因为懒。其实，<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。作为恒温动物，人类有最适宜的温度区间，一夜的睡眠让被窝里温暖又舒适，但被窝外却是寒气袭人。寒冷意味着需要消耗更多的能量，但如果继续躺在床上就可以保持体温，这时，刻进基因里的节能机制让人倾向于选择待在温暖的被窝里，这种机制来自住在山洞中恐惧饥寒的祖先们的经验，即尽可能地保存能量，并保护身体免受寒冷的伤害。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"这还是人类祖先留下的保命本领"},{"k":"B","t":"苏醒的过程也会受到环境温度的影响"},{"k":"C","t":"不妨耐心等一会儿再起床，让身体先“开机”"},{"k":"D","t":"适当赖床可以给身体足够的时间适应室内外的温度差异"}],"answer":"A","multi":false,"explanation":"<p>横线位于文段中间，需结合前后文分析。横线前提到有人认为早晨赖床是因为懒，接着通过“其实”进行转折，横线后具体解释了赖床是因为人类的节能机制，这种机制来自于祖先们住在山洞中恐惧饥寒的经验，是为了保存能量和保护身体免受寒冷伤害，故横线处应体现赖床源自祖先为保存能量、抵御寒冷而形成的生存策略，对应A项。<br>B项，“苏醒的过程”前后文均未提及，无中生有，且前文已经强调“睡醒了”，而非“苏醒的过程”，衔接不当，排除；<br>C项“耐心等一会儿再起床”及D项“适当赖床”均为给出的具体建议，而后文着重分析赖床的原因，与后文衔接不当，排除。<br>故正确答案为A。<br>【文段出处】科普中国《“天冷想赖床”不是懒，而是人类祖先留下的保命本领？》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":38,"pid":"p25bd314b90"},{"qid":"13504343","no":20,"type":"语句表达","module":"言语理解与表达","stem":"<p>郑和大航海发生在中国军事科技实力遥遥领先的背景下，郑和率领两百余艘船、两万多名将士的大舰队，实力远超大航海时代两三艘船、百余人的小船队，军事实力更是远超途经的国家和地区，但郑和船队坚持“共享太平之福”“敦睦邦交”“强不凌弱”的原则，奉行“厚往薄来”的政策，从来没有以大欺小，倚强凌弱，没有掠夺一两黄金白银，没有发动一场军事侵略，也没有占领一寸海外殖民地。“郑和大航海”<span class=\"exam-blank\" aria-label=\"填空横线\">&nbsp;</span>。<br>填入画横线部分最恰当的一项是：</p>","options":[{"k":"A","t":"在中外交流交往中发挥了积极的作用"},{"k":"B","t":"为中国的发展创造了稳定的国际环境"},{"k":"C","t":"是中华民族一脉相承的和平基因的最好例证"},{"k":"D","t":"为推动构建海洋命运共同体提供了中国方案"}],"answer":"C","multi":false,"explanation":"<p>横线位于文段结尾，需结合前文内容进行分析。文段开篇点明郑和大航海所处背景是中国军事科技实力遥遥领先的时候，郑和船队实力远超同时代其他船队。随后通过转折词“但”指出郑和船队始终秉持“共享太平之福”“敦睦邦交”“强不凌弱”的原则，奉行“厚往薄来”的政策，在航海过程中未进行掠夺、侵略和占领。这些行为充分彰显了和平友好的特质。故文段最后应进行总结，表明“郑和大航海”所展现的和平理念，对应C项。<br>A项，“在中外交流交往中发挥了积极的作用”偏离文段核心话题，文段重点强调的是郑和大航海过程中展现的和平理念，而非其在中外交流交往中的积极作用，排除；<br>B项，“为中国的发展创造了稳定的国际环境”无中生有，文段并没有表明中国因郑和大航海而获得了怎样稳定的国际环境，排除；<br>D项，“海洋命运共同体”是现代概念，文段围绕的是郑和大航海时期的和平行为，与文段时代背景不符，排除。<br>故正确答案为C。<br>【文段出处】光明网《向世界讲好“郑和大航海”故事》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":39,"pid":"p25bd314b90"},{"qid":"13504330","no":21,"type":"片段阅读","module":"言语理解与表达","stem":"<p>近年来，野外旅行、徒步旅行和露营等活动日益丰富。在选择户外旅游项目时，要选择经过科学论证的户外活动和线路，在保护自然环境和野生动物的前提下进行，与野生动物保持一定的距离。野生动物与人的生活环境不同，可能携带很多病原体，如鼠疫杆菌、狂犬病病毒和流感病毒等。从生态环境的角度来说，野生动物是整个生态系统的一部分，不管是扰乱、捉走饲养还是捕食，都会破坏当地的生态平衡。<br>这段文字意在强调：</p>","options":[{"k":"A","t":"野生动物有可能携带很多病原体"},{"k":"B","t":"户外旅行应与野生动物保持距离"},{"k":"C","t":"野生动物是整个生态系统的一部分"},{"k":"D","t":"户外旅行要选择经科学论证的路线"}],"answer":"B","multi":false,"explanation":"<p>文段开篇交代背景，指出野外旅行、徒步旅行和露营等活动日益丰富，随后提出对策，即在选择户外旅游项目时，应科学选择活动与线路，与野生动物保持距离。后文从两个角度对“与野生动物保持距离”这一观点进行解释说明，一方面野生动物可能携带很多病原体，另一方面野生动物对于维护当地生态平衡至关重要。故整个文段强调在户外旅行时要与野生动物保持距离，对应B项。<br>A、C两项，分别对应后文解释说明的其中一部分内容，表述片面且非重点，排除；<br>D项，缺少文段核心话题“野生动物”，排除。<br>故正确答案为B。<br>【文段出处】中国青年报《户外旅行应当与野生动物保持怎样的距离》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":40,"pid":"p25bd314b90"},{"qid":"13504377","no":22,"type":"片段阅读","module":"言语理解与表达","stem":"<p>大数据资源是来自于全社会的数据信息，在搜集数据信息的同时，社会的偏见也毫无意外地跟随着大数据。数据的偏见也造成了行政决策存在偏见。数据是算法运作的基础，人们通过大量的数据训练和计算得出行政决策的结论。可见，大数据的质量决定了行政决策的质量，如果采用不完全的天生有缺陷的大数据资源，比如带有歧视性的问答学习数据，那么算法产生偏见的概率将大大增加。<br>这段文字意在说明：</p>","options":[{"k":"A","t":"算法偏见带来的决策偏见难以避免"},{"k":"B","t":"避免算法偏见的关键在于数据搜集"},{"k":"C","t":"数据的质量和行政决策的质量息息相关"},{"k":"D","t":"基于数据训练的行政决策需要进一步评估"}],"answer":"C","multi":false,"explanation":"<p>文段开篇指出大数据资源来自全社会，社会偏见会跟随大数据，进而导致行政决策存在偏见。接着指出数据是算法运作的基础，人们依据数据训练和计算得出行政决策的结论。随后通过“可见”进行总结，强调大数据的质量决定了行政决策的质量，并表示如果采用有缺陷的大数据资源，算法产生偏见的概率会增加。故文段重在指出大数据的质量会影响行政决策的质量，对应C项。<br>A项，“难以避免”无中生有，且未提及文段主题词“行政决策”，排除；<br>B项，未提及文段主题词“行政决策”，排除；<br>D项，文段并未提及行政决策需要“进一步评估”，无中生有，且症结在于数据上，评估行政决策属于无关对策，排除。<br>故正确答案为C。<br>【文段出处】《行政决策中算法决策的风险识别与规制路径》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":41,"pid":"p25bd314b90"},{"qid":"13504325","no":23,"type":"片段阅读","module":"言语理解与表达","stem":"<p>免疫系统包含三大防线，皮肤、黏膜作为免疫系统的第一道防线，会阻止所有病毒或细菌的进入。当病毒或细菌已经侵入到人的身体时，巨噬细胞率先开始发挥作用。巨噬细胞能把外来异物如病毒或细菌吞入，靠内部的酶和各种活性物质杀死它们或者使其降解。当侵入人体的病毒或细菌数量过大时，巨噬细胞会释放化学信号，这时免疫系统的“保安”——白细胞能通过变形而穿过毛细血管壁，聚集到病菌入侵部位，将其包围、吞噬。<br>这段文字意在说明：</p>","options":[{"k":"A","t":"巨噬细胞的工作机制"},{"k":"B","t":"免疫系统如何抵御病菌"},{"k":"C","t":"白细胞具有包围、吞噬病菌的作用"},{"k":"D","t":"皮肤、黏膜是免疫系统的第一道防线"}],"answer":"B","multi":false,"explanation":"<p>文段开篇介绍免疫系统有三大防线，接着论述第一道防线会阻止所有病毒或细菌的进入，之后指出当病毒或细菌侵入人体后，巨噬细胞先开始发挥作用，最后论述当侵入人体的病毒或细菌数量过大时，白细胞会将病菌包围和吞噬，故文段为三方面的并列结构，详细介绍了免疫系统抵御病菌的三道防线，对应B项。<br>A项“巨噬细胞”、C项“白细胞”和D项“皮肤、黏膜”均为文段并列的一部分内容，表述片面，排除。<br>故正确答案为B。<br>【文段出处】光明日报《免疫系统是如何抵御病毒的》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":42,"pid":"p25bd314b90"},{"qid":"13504348","no":24,"type":"片段阅读","module":"言语理解与表达","stem":"<p>传统文博展示方式受场地空间、展览时间、文物特性等因素影响，限制了传播力与影响力的进一步提升，很难满足海量游人参观体验的需求。为此，可善用人工智能、虚拟现实等先进技术，推动文博展陈与文创产品数字化、沉浸式转化。比如，近期成立的全国博物馆文创联盟、博物馆策展联盟等平台，正以创新方式探索文博行业发展的新路径，带动中小型博物馆深度挖掘文物背后的故事，并运用新技术打破时空壁垒，以数字化方式让万千文博展品走进大众生活。<br>这段文字意在说明，文博展陈应：</p>","options":[{"k":"A","t":"拓展多空间，善用新技术"},{"k":"B","t":"活化老文物，挖掘新共鸣"},{"k":"C","t":"传承古智慧，融合新媒体"},{"k":"D","t":"展现历史美，利用新视角"}],"answer":"A","multi":false,"explanation":"<p>文段首先指出传统文博展示方式难以满足游人参观体验需求的问题，接着通过“为此”提出善用先进技术推动文博展陈与文创产品数字化、沉浸式转化这一对策，最后通过“比如”进行举例论证，故文段重点强调“为此”之后的对策，即善用先进技术推动文博展陈的发展，A项能够体现文段重点“善用先进技术”，当选。<br>B项“新共鸣”、C项“新媒体”、D项“新视角”均偏离主题词“先进技术”，排除。<br>故正确答案为A。<br>【文段出处】中国经济网《展创结合让文物活起来》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":43,"pid":"p25bd314b90"},{"qid":"13504374","no":25,"type":"片段阅读","module":"言语理解与表达","stem":"<p>我国农业中最富特色的资源，是基于特定区域生态与文化内涵的地理标志农产品。围绕地理标志专用标志、区域公用品牌创建与管理的理论研究成果数量日增，例如，以农业品牌、农产品区域公用品牌为关键词的论文数量不断增多，农业品牌建设的理论支撑体系不断构建。各高校相关团队的理论研究推动了我国农业品牌发展，特别是优质土特产的品牌化进程，也推动了相关支持政策的出台。<br>最适合做这段文字标题的是：</p>","options":[{"k":"A","t":"理论研究助力农业品牌化发展"},{"k":"B","t":"农业品牌理论研究迈上新台阶"},{"k":"C","t":"高校研究驱动农业产业提档升级"},{"k":"D","t":"加强地理标志农产品建设与保护"}],"answer":"A","multi":false,"explanation":"<p>文段开篇通过介绍我国农业中最富特色的资源，引出“地理标志农产品”这一话题，随后指出围绕地理标志专用标志、区域公用品牌创建与管理的理论研究成果数量日益增多，后文通过“例如”进行举例，展开论述这些研究成果对农业品牌建设提供了理论支撑。尾句进一步强调相关理论研究对农业品牌发展及相关政策出台的正向作用。故文段重点强调地理标志农产品相关的理论研究在农业品牌化中的关键作用，对应A项。<br>B项，“迈上新台阶”仅强调农业品牌理论研究自身的发展，未提及其对农业品牌化发展的推动作用，偏离文段重点，排除；<br>C项，“驱动农业产业提档升级”并未体现理论研究对农业品牌化发展的推动作用，偏离文段重点，排除；<br>D项，“地理标志农产品”仅为理论研究的对象，概念过窄，排除。<br>故正确答案为A。<br>【文段出处】经济日报《聚焦土特产打造区域发展金名片》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":44,"pid":"p25bd314b90"},{"qid":"13504356","no":26,"type":"片段阅读","module":"言语理解与表达","stem":"<p>早期地球是缺氧环境，大气中氧气含量很低。而在大约24亿年前，大气中的氧气含量急剧增加，促进了生物的繁衍，这被称为大氧化事件。但是大氧化事件的形成原因存在广泛争议，主流观点认为地球早期生物产氧和氧气的消耗处于平衡状态，导致氧气含量长期处于很低水平。而随着时间的推移，氧气的产生逐渐超过了消耗，导致氧气积累，并最终诱导发生大氧化事件。然而，目前对氧气积累的机制还缺乏明确认知。<br>这段文字接下来最可能讲的是：</p>","options":[{"k":"A","t":"早期地球氧气含量的变化状况"},{"k":"B","t":"大氧化事件对地球生态的影响"},{"k":"C","t":"大氧化前氧气积累机制的相关研究"},{"k":"D","t":"诱导大氧化事件发生的其他可能原因"}],"answer":"C","multi":false,"explanation":"<p>根据提问方式可知，本题为接语选择题，应在通读全文的基础上，重点关注文段最后论述的核心话题。文段开篇指出早期地球是缺氧环境，而在约24亿年前发生大氧化事件，氧气含量急剧增加，接着指出关于大氧化事件的成因存在争议，主流观点认为地球早期生物产氧和耗氧平衡使氧气含量低，后来氧气产生超过消耗导致氧气积累并引发大氧化事件，最后指出目前人们对氧气积累的机制缺乏明确认知。故文段最后重在阐述人们对氧气积累的机制还没有明确认知，根据话题保持一致性与连贯性的原则，文段接下来应围绕“氧气积累机制”展开论述，对应C项。<br>A项，文段已经阐述了早期地球氧气含量从低到高的变化情况，故为前文论述过内容，后文不会再次论述，排除；<br>B、D两项，均缺少文段尾句核心话题“氧气积累机制”，排除。<br>故正确答案为C。<br>【文段出处】中国科学院《二氧化硫光解是地球早期大气产氧的重要途径》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":45,"pid":"p25bd314b90"},{"qid":"13504326","no":27,"type":"片段阅读","module":"言语理解与表达","stem":"<p>西北太平洋台风主要形成于菲律宾以东的西北太平洋海域。这片海域全年温暖湿润，尤其是在夏季和秋季，海水温度升高，空气湿度加大，为台风的生成提供了充足能量。因此，西北太平洋成为全球台风生成最为活跃的区域之一。通常情况下，西北太平洋台风生成后沿西北方向移动，逐步影响中国、菲律宾、日本等国家。相比之下，南海被众多岛屿和大陆环抱，为台风活动提供了一个独特的舞台。由于位于热带和副热带气候带之间，南海夏季海温同样较高，这为台风的生成提供了充足的能量。而季风活动对南海台风的生成和发展有重要影响，使其具有明显的季节性和区域性特点。<br>这段文字未提及的是：</p>","options":[{"k":"A","t":"西北太平洋台风的影响范围"},{"k":"B","t":"南海台风与季风活动的关系"},{"k":"C","t":"南海台风的路径变化特点"},{"k":"D","t":"地形在台风形成中的作用"}],"answer":"C","multi":false,"explanation":"<p>A项，根据“通常情况下，西北太平洋台风生成后沿西北方向移动，逐步影响中国、菲律宾、日本等国家”可知，“影响范围”有所提及，排除；<br>B项，根据“而季风活动对南海台风的生成和发展有重要影响，使其具有明显的季节性和区域性特点”可知，“南海台风与季风活动的关系”有所提及，排除；<br>C项，文段中并未提及南海台风的路径变化特点，无中生有，当选；<br>D项，根据“南海被众多岛屿和大陆环抱，为台风活动提供了一个独特的舞台”可知，“地形在台风形成中的作用”有所提及，排除。<br>本题为选非题，故正确答案为C。<br>【文段出处】中国气象报社《生于海上，几多风雨？——谈谈台风的认知误区》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":46,"pid":"p25bd314b90"},{"qid":"13504338","no":28,"type":"语句表达","module":"言语理解与表达","stem":"<p>①地球科学在寻找、开发和利用自然资源中起着巨大作用<br>②还可以帮助人类与自然环境和谐共处<br>③从应用性上来看，它为人类如何利用、保护自然提供了科学的方法论<br>④并通过掌握自然灾害的规律与其作斗争<br>⑤从理论性上来说，它承担着揭示自然界奥秘与规律的使命<br>⑥地球科学是一门理论性、应用性都很强的自然科学<br>将以上6个句子重新排列，语序正确的一项是：</p>","options":[{"k":"A","t":"⑥⑤③①②④"},{"k":"B","t":"⑥③⑤①④②"},{"k":"C","t":"①②④⑥③⑤"},{"k":"D","t":"①④②⑥③⑤"}],"answer":"A","multi":false,"explanation":"<p>对比选项，确定首句。⑥句通过下定义的方式引出“地球科学”的话题，①句介绍地球科学的巨大作用，根据行文逻辑，应先下定义引出话题再描述具体作用，因此⑥句更适合作首句，排除C、D两项。<br>对比A、B两项，⑥句后所接句子分别为⑤句和③句。③句从“应用性”的角度对地球科学进行解释，⑤句从“理论性”的角度对地球科学进行解释，根据⑥句中“地球科学是一门理论性、应用性都很强的自然科学”可知，应先说“理论性”，再介绍“应用性”，故⑤句应在③句之前，排除B项，锁定A项。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":47,"pid":"p25bd314b90"},{"qid":"13504360","no":29,"type":"语句表达","module":"言语理解与表达","stem":"<p>①研究方法是指在研究中发现新现象、新事物，或提出新理论、新观点，揭示事物内在规律的工具和手段，是论文中不可或缺的部分<br>②学习了一种方法就相当于掌握了解决某一特定问题的一件工具，掌握的工具越多，解决问题的方法越多，研究能力也就越强<br>③“工欲善其事，必先利其器”，如果“事”属于学术研究，“器”便是研究方法<br>④在论文写作过程中，研究方法是十分重要的部分，撰写论文不仅要规范格式，写好综述，尤其还要掌握常用的研究方法<br>⑤能否做好学术研究，取决于是否使用了正确的、合适的研究方法<br>⑥它解释了研究如何进行以及数据来源、数据收集技术的使用等问题<br>将以上6个句子重新排列，语序正确的一项是：</p>","options":[{"k":"A","t":"①③⑤②④⑥"},{"k":"B","t":"②③①⑤⑥④"},{"k":"C","t":"③①④⑥②⑤"},{"k":"D","t":"④⑤①⑥③②"}],"answer":"D","multi":false,"explanation":"<p>观察选项，判断首句。①句介绍研究方法是什么，并指出其对论文的重要性，②句介绍学习、掌握研究方法后带来的意义，③句指出“器”是研究方法，④句通过“尤其”强调研究方法对论文的重要性，①句、③句和④句均可以引出“研究方法”这一话题，按照逻辑顺序，应先引出“研究方法”的话题，再介绍掌握研究方法之后的意义，故②句应该放在①③④三句之后，排除A、B两项。<br>继续观察发现，⑥句出现指代词“它”，可以考虑通过指代词捆绑解题。对比④⑥句、①⑥句，①句具体介绍研究方法的定义，指出研究方法是发现新现象，揭示事物内在规律的工具，⑥句中“研究如何进行以及数据来源、数据收集技术的使用”是对研究方法是论文写作工具的进一步说明，话题一致且内容衔接得当，④句指出在论文写作过程中要掌握常用的研究方法，与⑥句内容无法衔接，排除C项。<br>故正确答案为D。<br>【文段出处】微信公众号北体新传《2023年体育新闻传播研究方法与论文写作工作坊》</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"言语理解与表达"},"idx":48,"pid":"p25bd314b90"},{"qid":"13504397","no":1,"type":"数学运算","module":"数量关系","stem":"<p>某产品甲、乙两个经销商第一季度销售总额为200万元。第二季度，甲、乙的销售额比第一季度分别高20%、25%，且甲的销售额比乙高44万元。问上半年甲的销售额比乙高多少万元？</p>","options":[{"k":"A","t":"72"},{"k":"B","t":"76"},{"k":"C","t":"80"},{"k":"D","t":"84"}],"answer":"D","multi":false,"explanation":"<p>设甲第一季度销售额为a万元，则乙第一季度销售额为（200-a）万元，甲第二季度销售额为1.2a万元，乙第二季度销售额为1.25×（200-a）万元。根据题意可列式：1.2a-1.25×（200-a）=44，解得a=120，则甲第一季度销售额为120万元，乙第一季度销售额为200-120=80万元。故甲第一季度销售额比乙高120-80=40万元，根据题干甲第二季度销售额比乙高44万元，因此上半年甲的销售额比乙高40+44=84万元。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":49,"pid":"p25bd314b90"},{"qid":"13504262","no":2,"type":"数学运算","module":"数量关系","stem":"<p>某公司搬家需打包运走电脑主机和显示器各n台。有两种打包方式：一种是一箱装入6台主机和4台显示器，另一种是一箱装入3台主机和8台显示器。已知公司所有的电脑主机和显示器正好装满若干箱，问n可能的最小值为：</p>","options":[{"k":"A","t":"18"},{"k":"B","t":"24"},{"k":"C","t":"30"},{"k":"D","t":"36"}],"answer":"D","multi":false,"explanation":"<p>设第一种打包方式装满a箱，第二种打包方式装满b箱。根据电脑主机和显示器各有n台，可得：n=6a+3b=4a+8b，解得a=2.5b，代入可得n=18b。因为a、b均为箱子的数量，必须为正整数，故b取最小值2时，n取最小值为36。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":50,"pid":"p25bd314b90"},{"qid":"13504289","no":3,"type":"数学运算","module":"数量关系","stem":"<p>甲乙两部门组织户外团建，共设A、B、C三项活动。甲部门每人三项活动均参加1次，乙部门每人任选2项不同活动各参加1次。已知A、B、C三项活动分别有18人、16人、15人参加，问甲部门成员至多有多少人?</p>","options":[{"k":"A","t":"11"},{"k":"B","t":"12"},{"k":"C","t":"13"},{"k":"D","t":"14"}],"answer":"C","multi":false,"explanation":"<p>解法一：A、B、C三项活动参加的总人次为18+16+15=49，设甲部门为x人，乙部门为y人。根据题意，可得方程3x+2y=49，根据奇偶特性，可得x为奇数，排除B、D两项；根据问题“至多有多少人”，优先代入C项，解得y=5，符合题意，当选。<br>解法二：根据问题“至多”，可通过选项从大到小依次代入验证：<br>代入D项：甲部门14人，根据甲部门每人三项活动均参加1次，即A、B、C三项活动分别剩下4、2、1人次，4+2+1=7人次，奇数不能让乙部门每人任选2项不同活动各参加1次，排除；<br>代入C项：甲部门13人，根据甲部门每人三项活动均参加1次，即A、B、C三项活动分别剩下5、3、2人次，5+3+2=10人次，偶数能让乙部门每人任选2项不同活动各参加1次，符合题意，当选。<br>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":51,"pid":"p25bd314b90"},{"qid":"13504267","no":4,"type":"数学运算","module":"数量关系","stem":"<p>某公司甲部门男性员工比女性多2人，乙部门女性员工比男性多3人。已知甲、乙两部门女性员工共6人，问从甲、乙两部门中随机选出4人，恰好选到2名男员工和2名女员工的概率是：</p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-8348118af567dc06.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-027461423992aa4c.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-0f6bfd3f10aff5e6.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-ffd4f02d6132905c.png\" class=\"tex\"></p>"}],"answer":"B","multi":false,"explanation":"<p>设甲部门女性员工为x人，则甲部门男性员工有（x+2）人；乙部门女性员工有（6-x）人；乙部门男性员工有（6-x）-3=（3-x）人；甲、乙两个部门共有男性员工（x+2）+（3-x）=5人。</p><p>根据公式：概率<img src=\"assets/img/gongshi/formula-fddcf3dad07f2139.png\" class=\"tex\">，分析如下：</p><p>甲、乙两个部门共有5+6=11名员工，从中随机选出4人，总情况数<img src=\"assets/img/gongshi/formula-9b5ed633c4acef9c.png\" class=\"tex\">种。</p><p>要求选出的4名员工恰好为2名男员工和2名女员工：从5名男员工中随机选出2名，有<img src=\"assets/img/gongshi/formula-5c2a499487d3568e.png\" class=\"tex\">种情况；从6名女员工中随机选出2名，有<img src=\"assets/img/gongshi/formula-429fc4bdfdbe7eac.png\" class=\"tex\">种情况。则满足要求的情况数为<img src=\"assets/img/gongshi/formula-24818353bf0a1174.png\" class=\"tex\">种。</p><p>综上，所求概率<img src=\"assets/img/gongshi/formula-5185bb2873bf1c08.png\" class=\"tex\">。</p><p>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":52,"pid":"p25bd314b90"},{"qid":"13504394","no":5,"type":"数学运算","module":"数量关系","stem":"<p>某种农作物一年一熟，每次种植均有0.2的概率歉收，有0.3的概率丰产。问该农作物连续3年丰产的概率是连续3年歉收概率的多少倍？</p>","options":[{"k":"A","t":"2.5以下"},{"k":"B","t":"2.5~3之间"},{"k":"C","t":"3~4.5之间"},{"k":"D","t":"4.5以上"}],"answer":"C","multi":false,"explanation":"<p>根据题意，连续3年丰产的概率为0.3×0.3×0.3=0.027；连续3年歉收的概率为0.2×0.2×0.2=0.008。则该农作物连续3年丰产的概率是连续3年歉收概率的<img src=\"assets/img/gongshi/formula-e38be7b7b02c9cc0.png\" class=\"tex\">倍。</p><p>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":53,"pid":"p25bd314b90"},{"qid":"13504282","no":6,"type":"数学运算","module":"数量关系","stem":"<p>小张和小赵分别从甲、乙两地同时出发前往对方的出发地。小张出发时的速度是小赵的一半，两人匀速行进1小时后迎面相遇。此后小张开始均匀加速，最终比小赵晚到达1小时。问小张到达时的速度是小赵到达时速度的多少倍？</p>","options":[{"k":"A","t":"<p><img src=\"assets/img/gongshi/formula-a5d206687cc4baee.png\" class=\"tex\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-b2d7bb75429ee090.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-f965a32f38088929.png\" class=\"tex\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/gongshi/formula-26261b3e4e4cc592.png\" class=\"tex\"></p>"}],"answer":"C","multi":false,"explanation":"<p>根据题意，赋值小赵出发时每小时的速度为2，则小张出发时每小时的速度为1。两人同时从甲、乙两地出发，1小时后相遇，根据相遇公式：<img src=\"assets/img/gongshi/formula-74f05c31b9d3292f.png\" class=\"tex\">，可得<img src=\"assets/img/gongshi/formula-96e1496419036850.png\" class=\"tex\">。小赵从乙地到甲地全程用时为<img src=\"assets/img/gongshi/formula-ac562c72ea18a864.png\" class=\"tex\">小时，则小张从甲地到乙地全程用时为1.5+1=2.5小时。小张从相遇后到达乙地用时为2.5-1=1.5小时，小张从相遇后到达乙地距离等于小赵1小时行进距离=2×1=2，则小张从相遇后到达乙地的平均速度为<img src=\"assets/img/gongshi/formula-6c6f93222814057e.png\" class=\"tex\">。根据公式：均匀加速运动的平均速度<img src=\"assets/img/gongshi/formula-03429604db692442.png\" class=\"tex\">，可列式<img src=\"assets/img/gongshi/formula-fbe343ae5244645b.png\" class=\"tex\">，解得小张达到乙地时的速度为<img src=\"assets/img/gongshi/formula-3dcf78505e015406.png\" class=\"tex\">，则小张到达时的速度是小赵到达时速度的<img src=\"assets/img/gongshi/formula-b17cf51c71de898b.png\" class=\"tex\">倍。</p><p>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":54,"pid":"p25bd314b90"},{"qid":"13504419","no":7,"type":"数学运算","module":"数量关系","stem":"<p>甲生产线的效率是乙生产线的2倍，是丙生产线的3倍。某日8：00甲生产线先开始生产，此后乙、丙生产线也依次开始生产，9：00时甲的当日产量是乙的6倍，10：00时乙的当日产量是丙的4倍。问丙是几点开始生产的？</p>","options":[{"k":"A","t":"9：30"},{"k":"B","t":"9：20"},{"k":"C","t":"9：15"},{"k":"D","t":"9：10"}],"answer":"A","multi":false,"explanation":"<p>根据题意，赋值甲生产线每小时的效率为6，则乙的效率为3，丙的效率为2。某日8：00甲生产线开始生产，9：00时其当日产量=1×6=6，根据“9：00时甲的当日产量是乙的6倍”，可知9：00时乙的当日产量=6÷6=1，10：00时乙的当日产量为1+3×1=4。根据“10：00时乙的当日产量是丙的4倍”，可知10：00时丙的当日产量=4÷4=1，即已用时<img src=\"assets/img/gongshi/formula-778be1cbeda956b6.png\" class=\"tex\">小时=30分钟，则丙是从9：30开始生产的。</p><p>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":55,"pid":"p25bd314b90"},{"qid":"13504347","no":8,"type":"数学运算","module":"数量关系","stem":"<p>某梯形区域ABCD的俯视图如下图所示，AB、BC、AD长度相等，且为CD长度的一半，E、F、G分别为所在边的中点。现打算在阴影区域建艺术广场，如果梯形ABCD的总面积为120亩，问艺术广场的面积为多少亩？</p><p><img src=\"assets/img/timu/19598d3d78eb97d.png\" class=\"fig\" style=\"width:280px;height:140px;\"></p>","options":[{"k":"A","t":"<p>80</p>"},{"k":"B","t":"<p><img src=\"assets/img/gongshi/formula-2977500c38d2733d.png\" class=\"tex\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/gongshi/formula-51c23ff8fc9a1574.png\" class=\"tex\"></p>"},{"k":"D","t":"<p>100</p>"}],"answer":"D","multi":false,"explanation":"<p>如图所示，连接EG，过F向DC作垂线，垂足为H，与EG交于点M，根据题意可知<img src=\"assets/img/gongshi/formula-8142069d3b16c17e.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-35289d115625c0cd.png\" class=\"tex\">，E、F、G分别为所在边的中点，则梯形ABCD为等腰梯形，EG为等腰梯形ABCD的中位线，FH为等腰梯形ABCD的高，FM为<img src=\"assets/img/gongshi/formula-db6417a22d6a1c04.png\" class=\"tex\">的高，<img src=\"assets/img/gongshi/formula-57debf443b85ebc5.png\" class=\"tex\">，<img src=\"assets/img/gongshi/formula-2d067390b6a3fcf4.png\" class=\"tex\">，由图可知<img src=\"assets/img/gongshi/formula-d41d5458eb78a883.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-9daabc3a247d52cf.png\" class=\"tex\">，设AF长度为a，FH长度为2h，则AB=2a、CD=4a、FM=h，根据梯形面积公式：<img src=\"assets/img/gongshi/formula-6de25b280475f5f1.png\" class=\"tex\">，可得<img src=\"assets/img/gongshi/formula-7b968bce56ae145f.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-fc4b971372b90663.png\" class=\"tex\">；根据三角形面积公式：<img src=\"assets/img/gongshi/formula-b793fa111c59ce18.png\" class=\"tex\">，可得<img src=\"assets/img/gongshi/formula-a93a26cb222ab380.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-09810f8eab97ea82.png\" class=\"tex\">，则<img src=\"assets/img/gongshi/formula-2b727441a2cca120.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-034bf341d1208a4e.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-4c404b098247f88b.png\" class=\"tex\">，即<img src=\"assets/img/gongshi/formula-42a3fbad2b35092e.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-0d96880b20298818.png\" class=\"tex\">亩，因此<img src=\"assets/img/gongshi/formula-8905bc01d35b208b.png\" class=\"tex\">亩。</p><p><img src=\"assets/img/timu/19598d59eb81af3.png\" class=\"fig\" style=\"width:280px;height:150px;\"></p><p>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":56,"pid":"p25bd314b90"},{"qid":"13504532","no":9,"type":"数学运算","module":"数量关系","stem":"<p>甲、乙、丙3名研究生本学期已阅读了159篇本专业的学术论文。已知甲的阅读量比乙的一半多28篇，丙的阅读量比甲和乙的平均阅读量多18篇。问乙本学期至少还要再阅读多少篇，阅读量才能比丙多50%以上？</p>","options":[{"k":"A","t":"42"},{"k":"B","t":"48"},{"k":"C","t":"54"},{"k":"D","t":"60"}],"answer":"C","multi":false,"explanation":"<p>根据题意，设乙本学期已阅读2x篇，则甲本学期已阅读（x+28）篇，丙本学期已阅读<img src=\"assets/img/gongshi/formula-3be540a73ea69073.png\" class=\"tex\">篇。根据题意可列式：x+28+2x+1.5x+32=159，解得x=22，则乙本学期已阅读44篇，丙本学期已阅读65篇。设乙本学期还要阅读y篇即可比丙多50%以上，根据题意可列式：<img src=\"assets/img/gongshi/formula-bc33a7939f20546b.png\" class=\"tex\">，解得y&gt;53.5，y最少为54。</p><p>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":57,"pid":"p25bd314b90"},{"qid":"13504457","no":10,"type":"数学运算","module":"数量关系","stem":"<p>甲和乙两个科研单位共有99名工作人员。其中甲单位研究人员占本单位工作人员总数的75%，乙单位研究人员占本单位工作人员总数的88%。问甲单位的非研究人员比乙单位的非研究人员：</p>","options":[{"k":"A","t":"少不到5人"},{"k":"B","t":"少5人以上"},{"k":"C","t":"多不到5人"},{"k":"D","t":"多5人以上"}],"answer":"A","multi":false,"explanation":"<p>方法一：根据题意，甲单位研究人员数占甲单位人数的<img src=\"assets/img/gongshi/formula-4d6062529abecd64.png\" class=\"tex\">，可知甲单位人数为4的倍数；乙单位研究人员数占乙单位人数的<img src=\"assets/img/gongshi/formula-7f742925e02efc12.png\" class=\"tex\">，可知乙单位人数为25的倍数。再根据甲、乙两单位共有99人，可知：</p><p>若乙单位人数=25人，甲单位人数=99-25=74人，不是4的倍数，排除；</p><p>若乙单位人数=50人，甲单位人数=99-50=49人，不是4的倍数，排除；</p><p>若乙单位人数=75人，甲单位人数=99-75=24人，满足题干条件，成立。</p><p>再根据甲单位非研究人员数占甲单位人数的<img src=\"assets/img/gongshi/formula-4f774edd589e815d.png\" class=\"tex\">，乙单位非研究人员数占乙单位人数的<img src=\"assets/img/gongshi/formula-65f5b72a7ce388fb.png\" class=\"tex\">，可得甲单位非研究人员有<img src=\"assets/img/gongshi/formula-287a37a3cc0c9f2a.png\" class=\"tex\">人，乙单位非研究人员有<img src=\"assets/img/gongshi/formula-2cade961a5653cab.png\" class=\"tex\">人，所以甲单位的非研究人员比乙单位的非研究人员少3人。</p><p>方法二：根据题意，甲单位研究人员数占甲单位人数的<img src=\"assets/img/gongshi/formula-4d6062529abecd64.png\" class=\"tex\">，乙单位研究人员数占乙单位人数的<img src=\"assets/img/gongshi/formula-7f742925e02efc12.png\" class=\"tex\">，设甲单位总人数为4x人，乙单位总人数为25y人，因甲、乙两单位共有99人，可列式：4x+25y=99，由奇偶特性，4x为偶数，99为奇数，可知25y为奇数，则y为奇数：</p><p>若y=1，则4x=99-25=74，x为非整数，排除；</p><p>若y=3，则4x=99-75=24，x=6，满足题干条件，成立。</p><p>则甲单位总人数为4×6=24人，非研究人员为24×（1-75%）=6人；乙单位总人数为25×3=75人，非研究人员为75×（1-88%）=9人，所以甲单位的非研究人员比乙单位的非研究人员少3人。</p><p>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"数量关系"},"idx":58,"pid":"p25bd314b90"},{"qid":"13504534","no":1,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性。</p><p><img src=\"assets/img/timu/19599f24f228d13.png\" class=\"fig\" style=\"width:600px;height:271px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>元素组成不同，优先考虑属性规律。观察发现，题干已知图形的黑块均为轴对称图形，且都只有一条对称轴，而D项的黑块有两条对称轴，排除；继续观察发现，题干已知图形中都只有一个轴对称的空白面，该空白面也只有一条对称轴，且该空白面的对称轴与所在图形中黑块的对称轴从左到右依次呈垂直、平行位置关系交替，故？处图形黑块的对称轴与轴对称空白面的对称轴应为平行关系，只有A项符合。</p><p><img src=\"assets/img/timu/19599f449b62536.png\" class=\"fig\" style=\"width:600px;height:271px;\"></p><p>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":59,"pid":"p25bd314b90"},{"qid":"13504266","no":2,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性：</p><p><img src=\"assets/img/timu/195989147f9a402.png\" class=\"fig\" style=\"width:600px;height:271px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>解析一：元素组成不同，且无明显属性规律，考虑数量规律。观察发现，图形线条交叉明显，且每幅图均出现明显的弧线，考虑数曲直交点。曲直交点数均为1，排除B项；继续观察发现，题干图形曲直交点的特征依次为：曲线的端点与直线交叉、曲线的中段与直线“十字交叉”、曲线的端点与直线交叉、曲线的中段与直线“十字交叉”、曲线的端点与直线交叉，故？处图形的曲直交点应为曲线的中段与直线“十字交叉”，只有D项符合。<br>故正确答案为D。<br>解析二：<br>元素组成不同，且无明显属性规律，考虑数量规律。观察发现，图形线条交叉明显，且每幅图均出现明显的弧线，考虑曲直交点。曲直交点数均为1，排除B项；继续观察发现，题干图形曲直交点的特征为：曲线与直线（横线或竖线）相交、曲线与斜线相交、曲线与直线（横线或竖线）相交、曲线与斜线相交、曲线与直线（横线或竖线）相交，故？处图形的曲直交点应为曲线与斜线相交，只有A项符合。<br>故正确答案为A。<br>注：本题粉笔倾向于解析一。因为题干图形均只有一条曲线，曲线的端点或中段与直线相交的特征更明确；另外，解析二中图1为曲线与竖线相交，图3和图5为曲线与横线相交，其直线方向不完全一样。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":60,"pid":"p25bd314b90"},{"qid":"13504533","no":3,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性。</p><p><img src=\"assets/img/timu/19599f210815d03.png\" class=\"fig\" style=\"width:600px;height:281px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"A","multi":false,"explanation":"<p>元素组成相同，优先考虑位置规律。观察发现，图1与图2下侧两个白球位置没有发生变化，图2与图3左侧两个白球位置没有发生变化，图3与图4上侧两个白球位置没有发生变化，图4与图5右侧两个白球位置没有发生变化，按照此规律，图5与？处图形下侧两个白球位置应该没有发生变化，排除C、D两项；继续观察发现，每个图形中位置发生变化的两个白球在各自的框内顺时针平移1步，排除B项，只有A项符合。</p><p><img src=\"assets/img/timu/19599f33af0a8a0.png\" class=\"fig\" style=\"width:600px;height:281px;\"></p><p>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":61,"pid":"p25bd314b90"},{"qid":"13504268","no":4,"type":"图形推理","module":"判断推理","stem":"<p>从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定规律性：</p><p><img src=\"assets/img/timu/19598906628b543.png\" class=\"fig\" style=\"width:600px;height:261px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干图形均由黑白球组成，第一组图形黑球每次增加1个，白球每次增加2个；第二组图形黑球每次增加2个，白球每次增加1个，故？处图形应该包含6个黑球、3个白球，排除A、B两项；再次观察发现，题干图形都是由不同颜色的球组成，且明显分为内外两圈，考虑分开看。第一组图中，内圈的黑球依次顺时针增加1个，外圈的白球依次逆时针增加2个；第二组图中，前两幅图内圈的白球依次顺时针增加1个，外圈的两部分黑球各依次逆时针增加1个，？处图形应用此规律，只有D项符合。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":62,"pid":"p25bd314b90"},{"qid":"13504389","no":5,"type":"图形推理","module":"判断推理","stem":"<p>把下面的六个图形分为两类，使每一类图形都有各自的共同特征或规律，分类正确的一项是：</p><p><img src=\"assets/img/timu/195995551539412.png\" class=\"fig\" style=\"width:500px;height:394px;\"></p>","options":[{"k":"A","t":"①③④，②⑤⑥"},{"k":"B","t":"①②④，③⑤⑥"},{"k":"C","t":"①②⑤，③④⑥"},{"k":"D","t":"①④⑥，②③⑤"}],"answer":"B","multi":false,"explanation":"<p>本题为分组分类题目。元素组成不同，且无明显属性规律，考虑数量规律。观察发现，题干图形被分割，考虑面数量，但面数量无规律，且框内有明显一笔构成的线条，考虑笔画数。图①②④均为两笔画图形，图③⑤⑥均为一笔画图形，即图①②④为一组，图③⑤⑥为一组。<br>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":63,"pid":"p25bd314b90"},{"qid":"13504321","no":6,"type":"图形推理","module":"判断推理","stem":"<p>左下图为15个白色和3个灰色正方体组合而成的多面体，其可以由以下4项中除哪项外的3个小多面体组合而成？</p><p><img src=\"assets/img/timu/19598b5b562d240.png\" class=\"fig\" style=\"width:600px;height:157px;\"></p>","options":[{"k":"A","t":"A"},{"k":"B","t":"B"},{"k":"C","t":"C"},{"k":"D","t":"D"}],"answer":"D","multi":false,"explanation":"<p>本题考查立体拼合。题干多面体可以由A、B、C中的小多面体（A、C 两项中的小多面体需要先旋转）拼合而成，具体拼合过程如下图所示。</p><p><img src=\"assets/img/timu/19598b6238a67f3.png\" class=\"fig\" style=\"width:559px;height:275px;\"></p><p>本题为选非题，故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":64,"pid":"p25bd314b90"},{"qid":"13504308","no":7,"type":"图形推理","module":"判断推理","stem":"<p>左下图为两个正方体组合而成的长方体，这两个正方体的外表面展开图分别可能是：</p><p><img src=\"assets/img/timu/195b1a212bd95bd.png\" class=\"fig\" style=\"width:500px;height:239px;\"></p>","options":[{"k":"A","t":"①和②"},{"k":"B","t":"③和④"},{"k":"C","t":"①和④"},{"k":"D","t":"②和③"}],"answer":"A","multi":false,"explanation":"<p>将题干两个正方体的面标上字母序号，并在立体图形和外表面展开图的黑色半圆形面（面e和面g）中以黑色半圆形的直径所在的边为起始边，顺时针描边标号，如下图所示。</p><p><img src=\"assets/img/timu/1961835bf06b17b.jpg\" class=\"fig\" style=\"width:279px;height:173px;\"></p><p><img src=\"assets/img/timu/196ad7cbc8dcb50.png\" class=\"fig\" style=\"width:700px;height:195px;\"></p><p>图①中，标出黑色半圆形面中对应的边1和边4后发现，二者与题干右侧正方体中面g的边1和边4对应一致，可能是题干右侧正方体的外表面展开图。</p><p>图②中，标出黑色半圆形面与小直角三角形面的公共边（即边3）后发现，边3与题干左侧正方体中面e和面f的公共边对应一致，可能是题干左侧正方体的外表面展开图。</p><p>图③中，标出黑色半圆形面中对应的边1和边3后发现，边1与题干右侧正方体中面g的边1不对应一致，不可能是题干右侧正方体的外表面展开图；边3与题干左侧正方体中面e的边3不对应一致，不可能是题干左侧正方体的外表面展开图。故图③不可能是组成长方体的任一正方体的外表面展开图。</p><p>图④中，黑色半圆形面中对应的边1与题干右侧正方体中面g的边1不对应一致，不可能是题干右侧正方体的外表面展开图；黑色半圆形面中对应的边3与题干左侧正方体中面e的边3不对应一致，不可能是题干左侧正方体的外表面展开图。故图④不可能是组成长方体的任一正方体的外表面展开图。</p><p>综上，两个正方体的外表面展开图可能是①和②，对应A项。</p><p>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":65,"pid":"p25bd314b90"},{"qid":"13504323","no":8,"type":"定义判断","module":"判断推理","stem":"<p>情绪爆发策略是指在谈判过程中，当双方在某一个问题上相持不下，或者对方的态度、行为欠妥，要求不太合理时，通过情绪爆发、大发脾气等手段有意制造僵局逼迫对方，从而使对方被迫让步的谈判策略。<br>根据上述定义，下列符合情绪爆发策略的是：</p>","options":[{"k":"A","t":"小强脾气很是暴躁，做事没有耐心，经常一遇到不顺心的事就生气发火，家里人都不敢和他亲近"},{"k":"B","t":"老王作为公司负责人经常出去谈判，有时遇到对方提出无理要求，他总会大发脾气直接离席，不再与对方谈判"},{"k":"C","t":"谈判时，双方在某原则性问题上讨论了两天毫无进展，老周率领代表团临时离席表达自己的不满，最终对方作出了让步"},{"k":"D","t":"多多与父母沟通，要求买新手机，但被父母拒绝了，多多以离家出走要挟父母必须给他买，父母坚决不同意并对他进行了批评教育"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“在谈判过程中”、“双方在某一个问题上相持不下，或者对方的态度、行为欠妥，要求不太合理”、“通过情绪爆发、大发脾气等手段有意制造僵局逼迫对方”、“使对方被迫让步”。<br>第二步：逐一分析选项。<br>A项：小强脾气很是暴躁，做事没有耐心，遇到不顺心的事就生气发火，是日常做事的态度和行为，不符合“在谈判过程中”，家里人都不敢和他亲近，不符合“使对方被迫让步”，不符合定义，排除；<br>B项：老王在谈判过程中，遇到对方提出无理要求，不再与对方谈判，直接终止谈判而不是在继续的谈判中迫使对方让步，不符合“使对方被迫让步”，不符合定义，排除；<br>C项：谈判时，双方在某原则性问题上讨论了两天毫无进展，符合“在谈判过程中”、“双方在某一个问题上相持不下”，老周率领代表团临时离席表达自己的不满，最终对方作出了让步，符合“通过情绪爆发、大发脾气等手段有意制造僵局逼迫对方”、“使对方被迫让步”，符合定义，当选；<br>D项：多多以离家出走要挟父母必须给他买手机，但父母坚决不同意并对他进行了批评教育，证明父母没有让步，不符合“使对方被迫让步”，不符合定义，排除。<br>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":66,"pid":"p25bd314b90"},{"qid":"13504324","no":9,"type":"定义判断","module":"判断推理","stem":"<p>文化再生产是指文化模式、信仰、价值观、习俗、语言和其他社会行为在时间上的持续性和在不同社会成员之间的传递，通常通过教育系统、家庭、媒体、宗教机构和其他社会机构来实现。这些机构通过传授知识、规范和行为模式，帮助新一代成员学习并内化其文化。<br>根据上述定义，下列一定属于文化再生产的是：</p>","options":[{"k":"A","t":"小王在单亲家庭长大，从小养成了独立的性格"},{"k":"B","t":"在公司聚会上，小李向同事介绍自己的女朋友"},{"k":"C","t":"某小学开设了具有当地特色的民俗课，深受学生喜爱"},{"k":"D","t":"电视上不断滚动播放着某品牌家用饮水设备的广告语"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“文化模式、信仰、价值观、习俗、语言和其他社会行为”、“时间上的持续性”、“不同社会成员之间的传递”。<br>第二步：逐一分析选项。<br>A项：单亲家庭中长大的小王，养成了独立的性格，性格是一个人对现实的相对稳定的态度，不符合“文化模式、信仰、价值观、习俗、语言和其他社会行为”，养成独立的性格也不符合“不同社会成员之间的传递”，不符合定义，排除；<br>B项：小李在公司聚会上向同事们介绍自己的女朋友，传递给同事的信息是关于女朋友的基本情况，不符合“文化模式、信仰、价值观、习俗、语言和其他社会行为”，不符合定义，排除；<br>C项：某小学开设了具有当地特色的民俗课，民俗课可以将当地特色的民间文化通过课程的形式传递给同学们，符合“文化模式、信仰、价值观、习俗、语言和其他社会行为”、“不同社会成员之间的传递”，课程深受学生喜爱，同学们通过学习逐渐了解并认同这些民俗，有利于把当地特色民俗传承下去，符合“时间上的持续性”，符合定义，当选；<br>D项：某品牌家用饮水设备的广告语不断在电视上滚动播放，电视广告传递的是饮水设备的产品信息，不符合“文化模式、信仰、价值观、习俗、语言和其他社会行为”，不符合定义，排除。<br>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":67,"pid":"p25bd314b90"},{"qid":"13504331","no":10,"type":"定义判断","module":"判断推理","stem":"<p>主动收入就是用时间来换取金钱，它最大的特点就是必须花费时间和精力去获得，它是一种临时性收入，做一次工作得到一次回报。被动收入是不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入。<br>根据上述定义，下列各项收入中不属于被动收入的是：</p>","options":[{"k":"A","t":"银行存款的收益"},{"k":"B","t":"授权专利的许可费"},{"k":"C","t":"每月固定的兼职工资"},{"k":"D","t":"退休后每月领到的退休金"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>主动收入：“用时间来换取金钱”、“最大的特点就是必须花费时间和精力去获得”、“一种临时性收入，做一次工作得到一次回报”；<br>被动收入：“不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入”。<br>第二步：逐一分析选项。<br>A项：银行存款的收益无需花费额外的时间和精力，就可自动获得利息，符合“不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入”，符合“被动收入”定义，排除；<br>B项：授权专利的许可费无需花费额外的时间和精力，只要有人使用专利，就可获得许可费用，符合“不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入”，符合“被动收入”定义，排除；<br>C项：每月固定的兼职工资是需要花费时间和精力的，也是做一次工作得到一次回报，符合“用时间来换取金钱”、“最大的特点就是必须花费时间和精力去获得”、“一种临时性收入，做一次工作得到一次回报”，符合“主动收入”定义，不符合“被动收入”定义，当选；<br>D项：退休后每月领到的退休金无需花费额外的时间和精力，是按照当前的相关制度，每月自动发放的，符合“不需要花费多少时间和精力，也不需要照看，就可以自动获得的收入”，符合“被动收入”定义，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":68,"pid":"p25bd314b90"},{"qid":"13504336","no":11,"type":"定义判断","module":"判断推理","stem":"<p>生理性购买动机是指消费者为满足由保持和延续生命而引起的各种需要所产生的购买动机，社会性购买动机是指由社会性因素引起的消费者购买商品的动机。消费者的社会性购买动机是在后天社会因素的影响下形成的，一般可分为基本的社会性动机和高级的社会性动机。由社会交往、归属、自主等意念引起的购买动机，属于基本的社会性购买动机；由成就、威望等意念引起的购买动机，属于高级的社会性购买动机。<br>根据上述定义，下列属于社会性购买动机的是：</p>","options":[{"k":"A","t":"小乔每周都会和朋友出去约饭喝茶"},{"k":"B","t":"小华每周都会购买必要的生活物资"},{"k":"C","t":"小吴每周都会去社区参加义工活动"},{"k":"D","t":"小曼每个季度会购买刚需换季衣物"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>生理性购买动机：“消费者为满足由保持和延续生命而引起的各种需要所产生的购买动机”；<br>社会性购买动机：“由社会性因素引起的消费者购买商品的动机”、“分为基本的社会性动机和高级的社会性动机”；<br>基本的社会性购买动机：“由社会交往、归属、自主等意念引起的购买动机”；<br>高级的社会性购买动机：“由成就、威望等意念引起的购买动机”。<br>第二步：逐一分析选项。<br>A项：小乔每周都会和朋友出去约饭喝茶，符合“由社会交往、归属、自主等意念引起的购买动机”，符合“基本的社会性购买动机”定义，也符合“社会性购买动机”定义，当选；<br>B项：小华每周都会购买必要的生活物资，符合“消费者为满足由保持和延续生命而引起的各种需要所产生的购买动机”，符合“生理性购买动机”定义，不符合“社会性购买动机”定义，排除；<br>C项：小吴每周都会去社区参加义工活动，参加义工活动不涉及购买商品，不符合“由社会性因素引起的消费者购买商品的动机”，不符合“社会性购买动机”定义，排除；<br>D项：小曼每个季度会购买刚需换季衣物，符合“消费者为满足由保持和延续生命而引起的各种需要所产生的购买动机”，符合“生理性购买动机”定义，不符合“社会性购买动机”定义，排除。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":69,"pid":"p25bd314b90"},{"qid":"13504350","no":12,"type":"定义判断","module":"判断推理","stem":"<p>通常把公开出版发行的文献称为白色文献，把涉及机密无法公开出版发行的文献称为黑色文献。灰色文献是指采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献。灰色文献介于白色和黑色文献之间，已经发行但不易通过一般销售渠道购得。<br>根据上述定义，下列不属于灰色文献的是：</p>","options":[{"k":"A","t":"某行业协会印刷的提供给协会会员使用的技术规范"},{"k":"B","t":"某高校文学院为召开某次学术会议印刷的会议论文集"},{"k":"C","t":"某考古学杂志社每期印刷的受众极小的专业类学术期刊"},{"k":"D","t":"某企业印刷的在其内部流通的塑造企业文化的内部刊物"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>白色文献：“公开出版发行的文献”；<br>黑色文献：“涉及机密无法公开出版发行的文献”；<br>灰色文献：“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”、“已经发行但不易通过一般销售渠道购得”。<br>第二步：逐一分析选项。<br>A项：行业协会印刷的提供给协会会员使用的技术规范，是在协会的内部传播，不易通过一般销售渠道购得，符合“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”、“已经发行但不易通过一般销售渠道购得”，符合灰色文献的定义，排除；<br>B项：高校文学院为学术会议印刷的会议论文集，只适用在学术会议这一特定场合，尚未正式出版，也不能通过一般销售渠道购得，符合“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”、“已经发行但不易通过一般销售渠道购得”，符合灰色文献的定义，排除；<br>C项：考古学杂志社每期印刷的受众极小的学术期刊，虽然受众小，但也属于正式出版发行的文献，符合“公开出版发行的文献”，不符合“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”，符合白色文献的定义，不符合灰色文献的定义，当选；<br>D项：企业印刷的内部刊物只在其内部流通，并未正式出版，也不能通过一般销售渠道购得，符合“采用访问、会议、报告、通信等非正式科学交流方式传播的、尚未正式出版的文献”、“已经发行但不易通过一般销售渠道购得”，符合灰色文献的定义，排除。<br>本题为选非题，故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":70,"pid":"p25bd314b90"},{"qid":"13504340","no":13,"type":"定义判断","module":"判断推理","stem":"<p>非组织公众就是在公共关系对象中，处于无组织状态的个体的总和，非组织公众一般包括流散型公众、聚散型公众、周期型公众和固定型公众。①流散型公众：极为分散的最不稳定的公众；②聚散型公众：因某一临时事件、活动或某一共同问题临时聚集在一起的公众；③周期型公众：按一定的规律聚集在一起的公众；④固定型公众：由于兴趣、爱好、习惯的影响，比较集中地与某些组织、社团、商店、杂志社或某种商品生产厂家保持稳定联系的公众。<br>根据上述定义，下列对应正确的是：</p>","options":[{"k":"A","t":"乘坐北京开往上海高铁的旅客——④"},{"k":"B","t":"定期来某学校上课的函授班学员——③"},{"k":"C","t":"经常来社区棋牌室打牌的退休人员——②"},{"k":"D","t":"奥运会期间来田径体育场观看比赛的观众——①"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>①流散型公众：“极为分散”、“不稳定”；<br>②聚散型公众：“因某一临时事件、活动或某一共同问题”、“临时聚集”；<br>③周期型公众：“按一定的规律聚集在一起”；<br>④固定型公众：“由于兴趣、爱好、习惯的影响”、“与某些组织、社团、商店、杂志社或某种商品生产厂家保持稳定联系”。<br>第二步：逐一分析选项。<br>A项：乘坐北京开往上海高铁的旅客，“乘坐高铁”不符合“由于兴趣、爱好、习惯的影响”、“与某些组织、社团、商店、杂志社或某种商品生产厂家保持稳定联系”，不符合“固定型公众”定义，对应错误，排除；<br>B项：定期来某学校上课的函授班学员，“定期”符合“按一定的规律聚集在一起”，符合“周期型公众”定义，对应正确，当选；<br>C项：经常来社区棋牌室打牌的退休人员，“打牌”符合“由于兴趣、爱好、习惯的影响”，“经常来社区棋牌室”符合“与某些组织、社团、商店、杂志社或某种商品生产厂家保持稳定联系”，符合“固定型公众”定义，不符合“聚散型公众”定义，对应错误，排除；<br>D项：奥运会期间来田径体育场观看比赛的观众，“奥运会期间”“看比赛”符合“因某一临时事件、活动或某一共同问题”、“临时聚集”，符合“聚散型公众”定义，不符合“流散型公众”定义，对应错误，排除。<br>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":71,"pid":"p25bd314b90"},{"qid":"13504349","no":14,"type":"定义判断","module":"判断推理","stem":"<p>组合是指把多项看似不相关的事物通过想象加以联接，从而使之变成新的整体。按照组合方式不同，组合可分为三种：同类组合是指若干相同事物的组合；异类组合是指两种或两种以上不同事物的组合；重组组合是指分解事物的原来组合，再按照新的目标重新组合。<br>根据上述定义，下列属于重组组合的是：</p>","options":[{"k":"A","t":"在手机壳背后安一个钢圈，制成带支架的手机壳"},{"k":"B","t":"用100根雪糕棍制作成房子、坦克等手工艺制品"},{"k":"C","t":"在台灯底座安装紫外线灭蚊装置，设计出灭蚊灯"},{"k":"D","t":"将原来拼装成大风车的积木拆开，再拼装成飞机"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>组合：“把多项看似不相关的事物”、“通过想象加以联接”；<br>同类组合：“若干相同事物的组合”；<br>异类组合：“两种或两种以上不同事物的组合”；<br>重组组合：“分解事物的原来组合，再按照新的目标重新组合”。<br>第二步：逐一分析选项。<br>A项：在手机壳背后安装一个钢圈，是在原有的基础上加上一个东西，并未分解事物的原来组合，不符合“分解事物的原来组合，再按照新的目标重新组合”，不符合“重组组合”定义，排除；<br>B项：用100根雪糕棍制作成房子等手工艺制品，是同一种事物的组合，符合“若干相同事物的组合”，符合“同类组合”定义，不符合“重组组合”定义，排除；<br>C项：在台灯底座安装紫外线灭蚊装置，是在台灯底座原有的基础上安装，并未分解事物的原来组合，不符合“分解事物的原来组合，再按照新的目标重新组合”，不符合“重组组合”定义，排除；<br>D项：将原来拼装成大风车的积木拆开，符合“分解事物的原来组合”，再拼装成飞机，符合“再按照新的目标重新组合”，符合“重组组合”定义，当选。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":72,"pid":"p25bd314b90"},{"qid":"13504322","no":15,"type":"定义判断","module":"判断推理","stem":"<p>在经济学当中，运动防御是指企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域，以作为将来防御和进攻的中心。<br>根据上述定义，下列不属于运动防御的是：</p>","options":[{"k":"A","t":"某石油公司转型为能源公司，市场范围扩展到煤炭、核能、水利和化学等多方面"},{"k":"B","t":"某饮料公司发现许多人都在控制糖类摄入，于是推出了不少低糖饮料，以此来稳固市场"},{"k":"C","t":"某手机公司除了钻研提升手机性能以外，近几年还推出了智能穿戴、新能源汽车等多类产品"},{"k":"D","t":"某白酒公司认识到年轻人对白酒的消费意愿不强，于是拓展进入了冷冻食品等其他行业，实行多元化经营"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出定义关键词。<br>“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”。<br>第二步：逐一分析选项。<br>A项：石油公司将业务扩展至煤炭、核能、水利和化学等新的领域，符合“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”，符合定义，排除；<br>B项：低糖饮料属于饮料行业的细分产品，饮料公司并未向新的领域扩展业务，不符合“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”，不符合定义，当选；<br>C项：手机公司将业务扩展至智能穿戴、新能源汽车等新的领域，符合“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”，符合定义，排除；<br>D项：白酒公司将业务扩展至冷冻食品等新的领域，符合“企业不仅要坚守原有市场阵地，还要将业务范围扩展到新的有潜力的领域”，符合定义，排除。<br>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":73,"pid":"p25bd314b90"},{"qid":"12882038","no":16,"type":"类比推理","module":"判断推理","stem":"<p>讲解：精讲</p>","options":[{"k":"A","t":"山村：荒村"},{"k":"B","t":"火器：武器"},{"k":"C","t":"语词：热词"},{"k":"D","t":"乐事：趣事"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“精讲”一般指对某一知识点或某一内容进行深入、细致、有条理、全面的讲解，“精讲”是一种“讲解”，二者为种属关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“山村”指山区的村庄，“荒村”指荒僻的村落，有的山村是荒村，有的山村不是荒村，有的荒村是山村，有的荒村不是山村，二者为交叉关系，与题干逻辑关系不一致，排除；<br>B项：“火器”指的是利用炸药等的爆炸或燃烧性能起杀伤破坏作用的武器，“火器”是一种“武器”，二者为种属关系，但词语顺序与题干相反，与题干逻辑关系不一致，排除；<br>C项：“语词”指词、词组，“热词”指一个时期内使用频率极高的词语，“热词”是一种“语词”，二者为种属关系，与题干逻辑关系一致，当选；<br>D项：“乐事”指令人高兴的事，“趣事”指有趣的事，有的乐事是趣事，有的乐事不是趣事，有的趣事是乐事，有的趣事不是乐事，二者为交叉关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":74,"pid":"p25bd314b90"},{"qid":"13504285","no":17,"type":"类比推理","module":"判断推理","stem":"<p>发炎：发烧</p>","options":[{"k":"A","t":"饥饿：烧烤"},{"k":"B","t":"学习：考试"},{"k":"C","t":"祭祀：缅怀"},{"k":"D","t":"缺铁：贫血"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>发炎表现为红、肿、热、痛和功能障碍，所以发炎可以导致发烧，二者为因果对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：饥饿会导致胃肠疾病或者低血糖等，不会导致烧烤，二者不是因果对应关系，与题干逻辑关系不一致，排除；<br>B项：学习是为了准备考试，二者为方式目的的对应关系，与题干逻辑关系不一致，排除；<br>C项：祭祀是一种缅怀的方式，二者为方式目的的对应关系，与题干逻辑关系不一致，排除；<br>D项：缺铁可以导致贫血，二者为因果对应关系，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":75,"pid":"p25bd314b90"},{"qid":"13504387","no":18,"type":"类比推理","module":"判断推理","stem":"<p>覆：盖：覆盖</p>","options":[{"k":"A","t":"寒：酸：寒酸"},{"k":"B","t":"厚：重：厚重"},{"k":"C","t":"喉：舌：喉舌"},{"k":"D","t":"抚：摸：抚摸"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>“覆”、“盖”、“覆盖”均指遮盖，三者是近义关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：“寒”指冷、穷困，“酸”指像醋的气味或味道，二者不是近义关系，与题干逻辑关系不一致，排除；<br>B项：“厚”指扁平物体上下两个面的距离大，“重”指分量较大、程度深，二者不是近义关系，与题干逻辑关系不一致，排除；<br>C项：“喉”指介于咽和气管之间的部分，“舌”指舌头，二者不是近义关系，与题干逻辑关系不一致，排除；<br>D项：“抚”、“摸”、“抚摸”均指用手指轻轻触摸，三者是近义关系，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":76,"pid":"p25bd314b90"},{"qid":"13504408","no":19,"type":"类比推理","module":"判断推理","stem":"<p>公文：公告：通告</p>","options":[{"k":"A","t":"湿地：水松：水杉"},{"k":"B","t":"信息：图像：文字"},{"k":"C","t":"卷纸：卫生纸：餐巾纸"},{"k":"D","t":"运动器材：动感单车：引体向上"}],"answer":"B","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>公文是法定机关与组织在公务活动中，按照特定的体式、经过一定的处理程序形成和使用的书面材料；公告和通告都是公文的一种类型。公告和通告是并列关系，二者分别和公文构成种属关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：湿地是一种生态系统，水松和水杉是湿地中的两种植物。水松和水杉是并列关系，二者分别和湿地是地点对应关系，与题干逻辑关系不一致，排除；<br>B项：图像和文字是两种不同的信息。图像和文字是并列关系，二者分别和信息构成种属关系，与题干逻辑关系一致，当选；<br>C项：卷纸通常指的是一种用于卫生、清洁等目的的长条形、可卷曲的纸张；卫生纸和餐巾纸是不同用途的两种生活用纸。卫生纸和餐巾纸是并列关系，二者分别和卷纸构成交叉关系，与题干逻辑关系不一致，排除；<br>D项：动感单车是一种运动器材，但引体向上是一种动作，与题干逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":77,"pid":"p25bd314b90"},{"qid":"13504529","no":20,"type":"类比推理","module":"判断推理","stem":"<p>灌木树：银杏树：观叶树</p>","options":[{"k":"A","t":"风景画：工笔画：中国画"},{"k":"B","t":"国内法：诉讼法：程序法"},{"k":"C","t":"燕尾服：体操服：运动服"},{"k":"D","t":"学术会：咨询会：线上会"}],"answer":"C","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>灌木树是指没有明显的主干、呈丛生状态比较矮小的树木，银杏树是乔木树而不是灌木树，前两词是反向种属关系。观叶树是指叶形和叶色美丽的植物，银杏树树叶具有很高的观赏价值，是观叶树，后两词是种属关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：风景画和工笔画是从不同的划分角度去命名的，二者为交叉关系，与题干逻辑关系不一致，排除；<br>B项：国内法和诉讼法是从不同的划分角度去命名的，二者为交叉关系，与题干逻辑关系不一致，排除；<br>C项：体操服不是燕尾服，前两词是反向种属关系，体操服是运动服，后两词是种属关系，与题干逻辑关系一致，当选；<br>D项：学术会和咨询会是从不同的划分角度去命名的，二者为交叉关系，与题干逻辑关系不一致，排除。<br>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":78,"pid":"p25bd314b90"},{"qid":"13504405","no":21,"type":"类比推理","module":"判断推理","stem":"<p>刑罚：改造罪犯：处罚</p>","options":[{"k":"A","t":"格言：指导言行：语句"},{"k":"B","t":"审计：收入分配：监督"},{"k":"C","t":"比喻：生动描写：借喻"},{"k":"D","t":"科研：本质规律：活动"}],"answer":"A","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>刑罚是指审判机关依据刑事法律对罪犯所施行的法律制裁。刑罚是处罚的一种，二者为种属关系；刑罚的功能是改造罪犯，二者为功能的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：格言是指含有劝诫和教育意义的话。格言是语句的一种，二者为种属关系；格言的功能是指导言行，二者为功能的对应关系，与题干逻辑关系一致，当选；<br>B项：审计是指由专设机关依照法律对国家各级政府及金融机构、企业事业组织的重大项目和财务收支进行事前和事后的监督、检查。审计是监督的一种具体形式，二者为种属关系；但审计的功能是监督和检查收入分配，收入分配是审计的对象，二者为作用对象的对应关系，与题干逻辑关系不一致，排除；<br>C项：借喻是比喻的一种，直接借比喻的事物来代替被比喻的事物，被比喻的事物和比喻词都不出现。借喻和比喻是种属关系，但词语顺序与题干相反；比喻的功能是生动描写，二者为功能的对应关系，与题干逻辑关系不一致，排除；<br>D项：科研是活动的一种，二者为种属关系；但科研的功能是探索本质规律，本质规律是科研的对象，二者为作用对象的对应关系，与题干逻辑关系不一致，排除。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":79,"pid":"p25bd314b90"},{"qid":"13504281","no":22,"type":"类比推理","module":"判断推理","stem":"<p>加大培训：稳定就业：扩充岗位</p>","options":[{"k":"A","t":"预防流感：接种疫苗：增强体质"},{"k":"B","t":"增加营收：提高利润：降低成本"},{"k":"C","t":"建立信任：有效沟通：促成合作"},{"k":"D","t":"浸泡催芽：翻土播种：浇水追肥"}],"answer":"B","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>加大培训和扩充岗位都是为了稳定就业，第一词和第三词都与第二词构成方式目的对应关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：接种疫苗和增强体质都是为了预防流感，第二词和第三词都与第一词构成方式目的对应关系，与题干逻辑关系不一致，排除；<br>B项：增加营收和降低成本都是为了提高利润，第一词和第三词都与第二词构成方式目的对应关系，与题干逻辑关系一致，当选；<br>C项：建立信任和有效沟通都是为了促成合作，第一词和第二词都与第三词构成方式目的对应关系，与题干逻辑关系不一致，排除；<br>D项：先浸泡催芽，然后翻土播种，最后浇水追肥，三者为动作先后的对应关系，与题干逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":80,"pid":"p25bd314b90"},{"qid":"13504307","no":23,"type":"类比推理","module":"判断推理","stem":"<p>法定节日：传统节日：纪念节日</p>","options":[{"k":"A","t":"国家秘密：商业秘密：工作秘密"},{"k":"B","t":"劳动产品：手工产品：文创产品"},{"k":"C","t":"儿童医院：公立医院：私立医院"},{"k":"D","t":"帆布书包：双肩书包：学生书包"}],"answer":"D","multi":false,"explanation":"<p>第一步：判断题干词语间逻辑关系。<br>法定节日是由国家法律、法规统一规定的用以开展纪念、庆祝活动的节日；传统节日是一个民族或地区在长期历史发展中形成的、具有特定文化内涵和社会功能的节日；纪念节日一般是指某个国家为了纪念重大事件、伟人、先烈等特定的节日。三者是从不同的划分角度去命名的，互为交叉关系。<br>第二步：判断选项词语间逻辑关系。<br>A项：国家秘密是指关系国家安全和利益，依照法定程序确定，在一定时间内只限一定范围的人员知悉的事项；商业秘密是指能给权利人带来经济利益，且已采取保密措施的技术信息和经营信息，主体是企业、个体工商户等市场主体；工作秘密是指机关单位在公务活动里产生的内部事项。三者是针对三个不同的主体，互为并列关系，与题干逻辑关系不一致，排除；<br>B项：手工产品、文创产品均属于劳动产品，后两词与第一词均为种属关系，与题干逻辑关系不一致，排除；<br>C项：公立医院与私立医院为并列关系，与题干逻辑关系不一致，排除；<br>D项：帆布书包是根据书包的材质来划分，双肩书包是根据书包的背负方式来划分，学生书包是根据背负书包的主体来划分，三者是从不同的划分角度去命名的，互为交叉关系，与题干逻辑关系一致，当选。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":81,"pid":"p25bd314b90"},{"qid":"12882040","no":24,"type":"类比推理","module":"判断推理","stem":"<p>（    ） 对于 泄洪 相当于 挂号 对于 （    ）</p>","options":[{"k":"A","t":"水库；问诊"},{"k":"B","t":"开闸；看病"},{"k":"C","t":"防溃坝；查病历"},{"k":"D","t":"减水压；开药方"}],"answer":"B","multi":false,"explanation":"<p>逐一代入选项。<br>A项：水库有泄洪的功能，二者为功能对应关系；先挂号，再问诊，二者为时间先后顺序对应关系，前后逻辑关系不一致，排除；<br>B项：开闸是为了泄洪，二者为方式目的对应关系；挂号是为了看病，二者为方式目的对应关系，前后逻辑关系一致，当选；<br>C项：泄洪是为了防溃坝，二者为方式目的对应关系；查病历与挂号无明显逻辑关系，前后逻辑关系不一致，排除；<br>D项：泄洪有减水压的作用，二者为功能对应关系；先挂号，再开药方，二者为时间先后顺序对应关系，前后逻辑关系不一致，排除。<br>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":82,"pid":"p25bd314b90"},{"qid":"13504319","no":25,"type":"类比推理","module":"判断推理","stem":"<p>（    ） 对于 斜拉桥 相当于 燃油车 对于（    ）</p>","options":[{"k":"A","t":"拱式桥；摩托车"},{"k":"B","t":"钢架桥；人力车"},{"k":"C","t":"人行桥；网约车"},{"k":"D","t":"独木桥；违章车"}],"answer":"C","multi":false,"explanation":"<p>逐一代入选项。<br>A项：拱式桥和斜拉桥是两种不同结构类型的桥，二者是并列关系；有的摩托车是燃油车，有的燃油车是摩托车，有的摩托车不是燃油车，有的燃油车不是摩托车，二者是交叉关系，前后逻辑关系不一致，排除；<br>B项：有的钢架桥是斜拉桥，有的斜拉桥是钢架桥，有的钢架桥不是斜拉桥，有的斜拉桥不是钢架桥，二者是交叉关系；燃油车和人力车是两种不同动力来源的车，二者是并列关系，前后逻辑关系不一致，排除；<br>C项：有的人行桥是斜拉桥，有的斜拉桥是人行桥，有的人行桥不是斜拉桥，有的斜拉桥不是人行桥，二者是交叉关系；有的网约车是燃油车，有的燃油车是网约车，有的网约车不是燃油车，有的燃油车不是网约车，二者是交叉关系，前后逻辑关系一致，当选；<br>D项：独木桥和斜拉桥是两种不同结构类型的桥，二者是并列关系；有的违章车是燃油车，有的燃油车是违章车，有的违章车不是燃油车，有的燃油车不是违章车，二者是交叉关系，前后逻辑关系不一致，排除。<br>故正确答案为C。<br>注：有同学可能会认为B项的钢架桥和斜拉桥是按照结构划分的两种不同的桥梁，但是按照结构划分的应为“刚”架桥，选项中的“钢”架桥为按照材料划分的，二者并不相同。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":83,"pid":"p25bd314b90"},{"qid":"13504373","no":26,"type":"逻辑判断","module":"判断推理","stem":"<p>汉朝建立后，在秦咸阳故都的基础上建立了长安城。经过西汉末年、东汉末年和魏晋南北朝期间的长期战乱，长安城日益凋敝。城门、宫殿、武库及城南的礼制建筑等都在战火中被毁，唐朝建立后，虽然汉都长安已破败不堪，但是唐长安城仍与其关联密切。有学者认为，汉长安城实际上成为了唐长安城的一部分。<br>以下哪项如果为真，最能支持上述学者的观点？</p>","options":[{"k":"A","t":"汉长安城的渭南内城被划入了唐长安城西北角的禁苑，成为专供皇室游猎的场所"},{"k":"B","t":"唐朝政府设有专门的机构管理汉长安城的主要遗迹，还曾对汉未央宫进行过修葺扩建"},{"k":"C","t":"至唐朝时，汉长安城的城墙城门、部分宫殿、武库、官署和角楼等建筑及道路都还保留完好"},{"k":"D","t":"隋朝建立都城时，曾从汉长安城的宫室建筑拆取了一些大型建材，这些都为后世的唐朝所继承"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：汉长安城实际上成为了唐长安城的一部分。<br>论据：无。<br>本题只有论点，没有论据，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：汉长安城的渭南内城被划入了唐长安城西北角的禁苑，说明汉长安城确实成为了唐长安城的一部分，补充论据，可以加强，当选；<br>B项：唐朝政府会管理汉长安城的主要遗迹并修葺扩建过汉未央宫，但汉长安城的主要遗迹和汉未央宫是否被纳入了唐长安城并不清楚，为不明确项，无法加强，排除；<br>C项：汉长安城的部分建筑及道路至唐朝时仍保留完好，但其是否被纳入了唐长安城并不清楚，为不明确项，无法加强，排除；<br>D项：唐朝部分建筑的“建材”来自汉长安城的宫室建筑，而论点讨论的是汉长安“城”实际上成为了唐长安城的一部分，建材无法代表城池，话题不一致，无法加强，排除。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":84,"pid":"p25bd314b90"},{"qid":"13504379","no":27,"type":"逻辑判断","module":"判断推理","stem":"<p>自己烧水喝与直接喝包装水，哪一种更健康？一种观点认为，包装水中含有大量的微塑料，直接喝包装水会使微塑料进入体内，危害健康，因此自己烧水喝比直接喝包装水健康，另一种观点则认为，当前微塑料污染无处不在，海洋、污水、淡水、饮用水中均含有微塑料，因此自己烧水喝与直接喝包装水对健康的影响是一样的。<br>以下哪项如果为真，最能削弱第二种观点？</p>","options":[{"k":"A","t":"在日常饮食中应尽量减少微塑料进入体内"},{"k":"B","t":"把水烧开后，可以除去高达84%的微塑料"},{"k":"C","t":"自然水域中的微塑料已危害到野生动物健康"},{"k":"D","t":"微塑料可以进入血液，甚至抵达心脏和大脑"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：自己烧水喝与直接喝包装水对健康的影响是一样的。<br>论据：当前微塑料污染无处不在，海洋、污水、淡水、饮用水中均含有微塑料。<br>本题论点讨论是自己烧水喝与直接喝包装水对健康的影响相同，论据讨论的是所有水中都含有微塑料，二者话题一致，削弱优先考虑削弱论点。<br>第二步：逐一分析选项。<br>A项：指出日常饮食中应该减少微塑料的摄入，与论点讨论的自己烧水喝与直接喝包装水对健康的影响相同无关，话题不一致，无法削弱，排除；<br>B项：指出水烧开后可以除去84%的微塑料，说明自己烧水喝比直接喝包装水摄入的微塑料少，因此自己烧水喝与直接喝包装水对健康的影响不一样，削弱论点，可以削弱，当选；<br>C项：指出自然水域中的微塑料危害到“野生动物”的健康，与论点讨论的“人体健康”无关，话题不一致，无法削弱，排除；<br>D项：指出微塑料的危害，但不清楚自己烧的水与直接饮用包装水中的微塑料含量是否相同，为不明确项，无法削弱，排除。<br>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":85,"pid":"p25bd314b90"},{"qid":"13504369","no":28,"type":"逻辑判断","module":"判断推理","stem":"<p>研究人员比较了过去几年自动驾驶车辆和人类驾驶车辆的相关数据发现，一般情况下，与人类驾驶相比，自动驾驶车辆在执行常规驾驶任务，如保持车道位置和根据车流调整位置时更安全，研究人员认为，以自动驾驶车辆代替人类驾驶车辆上路可以大大减少交通事故。<br>上述结论需要补充以下哪项作为前提？</p>","options":[{"k":"A","t":"当前交通事故主要发生在常规驾驶任务中"},{"k":"B","t":"过去几年自动驾驶车辆技术水平发展迅速"},{"k":"C","t":"自动驾驶车辆可以为道路交通提供精准导航"},{"k":"D","t":"自动驾驶车辆和人类驾驶车辆存在风险差异"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：以自动驾驶车辆代替人类驾驶车辆上路可以大大减少交通事故。<br>论据：一般情况下，与人类驾驶相比，自动驾驶车辆在执行常规驾驶任务，如保持车道位置和根据车流调整位置时更安全。<br>论据和论点都在说自动驾驶车辆比人类驾驶更安全，二者话题一致，且提问方式为“前提”，加强优先考虑补充必要条件。<br>第二步：逐一分析选项。<br>A项：选项表明当前交通事故主要发生在常规驾驶任务中，如果该项不成立，即交通事故大多都不是发生在常规驾驶任务中，那么就无法根据论据“在执行常规驾驶任务时，自动驾驶车辆比人类驾驶更安全”得出论点，因此该项是论点成立的必要条件，可以加强，当选；<br>B项：选项表明过去几年自动驾驶车辆技术水平发展迅速，但不明确以自动驾驶车辆代替人类驾驶车辆上路是否可以减少交通事故，无法加强，排除；<br>C项：选项表明自动驾驶车辆可以为道路交通提供精准导航，说的是自动驾驶车辆的导航能力，而论点说的是自动驾驶车辆的安全性，话题不一致，无法加强，排除；<br>D项：选项表明自动驾驶车辆和人类驾驶车辆存在风险差异，但不明确以自动驾驶车辆代替人类驾驶车辆上路是否可以减少交通事故，无法加强，排除。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":86,"pid":"p25bd314b90"},{"qid":"13504386","no":29,"type":"逻辑判断","module":"判断推理","stem":"<p>紫外线照射会使黑色素过度积累，早前使用的一些抑制黑色素合成的化合物，如对苯二酚，对人类皮肤有毒性，已不再推荐作为美白剂使用，为此研究人员纷纷寻找应用在化妆品行业中更安全的美白剂。近日，研究人员从一种常见的寄居于人类皮肤上的细菌——结核硬脂酸棒状杆菌中，发现了酪氨酸酶抑制剂。实验证实，酪氨酸酶对人体细胞无毒，适合用于对抗色素沉着。研究人员认为，酪氨酸酶是一种安全有效的美白剂。<br>以下哪项如果为真，最能支持上述结论？</p>","options":[{"k":"A","t":"除了酪氨酸酶，在天然细菌中暂时还没找到其他能替代对苯二酚的物质"},{"k":"B","t":"酪氨酸酶具有抗菌、抗癌等有益特性，进一步增强了其在各种治疗应用中的潜力"},{"k":"C","t":"结核硬脂酸棒状杆菌是寄居在皮肤上的细菌，通常会成为与人体共生的细菌，其衍生产物毒性低"},{"k":"D","t":"结核硬脂酸棒状杆菌是人类皮肤表面的正常菌群，在一般情况下并不致病，即使致病也可使用抗生素治疗"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：酪氨酸酶是一种安全有效的美白剂。<br>论据：研究人员从一种常见的寄居于人类皮肤上的细菌——结核硬脂酸棒状杆菌中，发现了酪氨酸酶抑制剂。实验证实，酪氨酸酶对人体细胞无毒，适合用于对抗色素沉着。<br>本题论据说的是“酪氨酸酶对人体细胞无毒，适合用于对抗色素沉着”，进而得出论点“酪氨酸酶是一种安全有效的美白剂”，二者话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：指出在天然细菌中暂时还没找到其他能替代对苯二酚的物质，但论点讨论的是酪氨酸酶是否是安全有效的美白剂，话题不一致，无法加强，排除；<br>B项：指出酪氨酸酶具有抗菌、抗癌等有益特性，但论点讨论的是酪氨酸酶是否是安全有效的美白剂，抗菌、抗癌等特性与美白剂的安全性和有效性没有直接关联，无法加强，排除；<br>C项：指出结核硬脂酸棒状杆菌是寄居在皮肤上的细菌，通常会成为与人体共生的细菌，其衍生产物毒性低，而酪氨酸酶是从结核硬脂酸棒状杆菌中发现的，说明酪氨酸酶具有安全性，补充论据，可以加强，当选；<br>D项：指出结核硬脂酸棒状杆菌在一般情况下并不致病，即使致病也可使用抗生素治疗，但并没有提到结核硬脂酸棒状杆菌中的酪氨酸酶是否可以作为安全有效的美白剂，话题不一致，无法加强，排除。<br>故正确答案为C。<br>特别说明：<br>本题文段用词不够精准，混淆了“酪氨酸酶”和“酪氨酸酶抑制剂”，文段想表达的意思是“酪氨酸酶”会催化黑色素合成，而“酪氨酸酶抑制剂”可以抑制黑色素合成，从而美白。<br>所以最后论点讨论“酪氨酸酶抑制剂”美白是否安全有效。只有C项说结核硬脂酸棒状杆菌的“衍生产物”（即“酪氨酸酶抑制剂”）毒性低，即相对来说是安全的，择优选择C项。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":87,"pid":"p25bd314b90"},{"qid":"13504381","no":30,"type":"逻辑判断","module":"判断推理","stem":"<p>为研究雄性小鼠肠道微生物组对后代健康的影响，研究人员给雄性小鼠注射了6周抗生素，导致它们肠道微生物多样性和丰富度下降，结果发现这些小鼠的后代出生时体重较轻、生长严重受限以及过早死亡的概率更高，研究人员认为，这一效应与雄性生殖系统对微生物组失衡的反应有关，这种反应可能会增加胎盘功能不全的风险，因此，雄性小鼠肠道微生物组紊乱可能会影响后代健康。<br>以下哪项如果为真，最能支持上述结论？</p>","options":[{"k":"A","t":"在雌性小鼠受孕前，若紊乱的雄性小鼠肠道微生物组得到恢复，则能降低后代不健康的风险"},{"k":"B","t":"研究中雄性小鼠生殖系统对微生物组失衡的反应包括激素信号受损和睾丸代谢物特征改变"},{"k":"C","t":"导致雄性小鼠肠道微生物组紊乱的环境因素会引发宿主的生理和疾病反应"},{"k":"D","t":"对哺乳动物而言，雄性的健康状况很有可能会遗传给后代"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：雄性小鼠肠道微生物组紊乱可能会影响后代健康。<br>论据：研究人员给雄性小鼠注射了6周抗生素，导致它们肠道微生物多样性和丰富度下降，结果发现这些小鼠的后代出生时体重较轻、生长严重受限以及过早死亡的概率更高，研究人员认为，这一效应与雄性生殖系统对微生物组失衡的反应有关，这种反应可能会增加胎盘功能不全的风险。<br>本题论点和论据均在讨论雄性小鼠肠道微生物对后代健康的影响，论点论据话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：选项说在雌性小鼠受孕前，紊乱的雄性小鼠肠道微生物组如果恢复，则能降低后代不健康的风险，补充反面论据说明雄性小鼠肠道微生物组紊乱确实会影响后代健康，补充论据，可以加强，当选；<br>B项：选项说研究中雄性小鼠生殖系统对微生物组失衡的反应包括哪些特征改变，但论点讨论的是雄性小鼠肠道微生物组紊乱是否会影响后代健康，话题不一致，无法加强，排除；<br>C项：选项说导致雄性小鼠肠道微生物组紊乱的环境因素会引发宿主的生理和疾病反应，但论点讨论的是雄性小鼠肠道微生物组紊乱是否会影响后代健康，话题不一致，无法加强，排除；<br>D项：选项说哺乳动物雄性的健康状况很有可能会遗传给后代，但是不确定雄性小鼠肠道微生物组紊乱是否会影响后代健康，为不明确选项，无法加强，排除。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":88,"pid":"p25bd314b90"},{"qid":"13504368","no":31,"type":"逻辑判断","module":"判断推理","stem":"<p>研究人员调查了负面情绪（包括愤怒、焦虑和悲伤）是否会对人体产生不利影响。研究中，280名成年人被随机分配4项情绪任务之一，包括回忆让他们愤怒的个人经历；回忆令自己感到焦虑的事件；阅读一系列引发悲伤的令人沮丧的句子；或者反复从1数到100以诱发中性情绪状态。研究发现，从任务完成后的0分钟到40分钟，回忆愤怒经历会导致血管舒张能力受损。40分钟后，这种状况才消失，而相较于愤怒，焦虑和悲伤情绪并没有引发血管内壁功能的显著变化。研究人员据此认为，愤怒会增加患动脉粥样硬化的风险。<br>上述论证的成立需要补充以下哪项作为前提？</p>","options":[{"k":"A","t":"血管舒张能力受损引发血管内壁功能的显著变化"},{"k":"B","t":"回忆愤怒的经历与心血管疾病之间存在显著关联"},{"k":"C","t":"血管舒张能力受损会增加患动脉粥样硬化的风险"},{"k":"D","t":"研究开始前，受试者都未检出血管舒张能力受损"}],"answer":"C","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：愤怒会增加患动脉粥样硬化的风险。<br>论据：回忆愤怒经历会导致血管舒张能力受损，而焦虑和悲伤情绪并没有引发血管内壁功能的显著变化。<br>本题论点说的是“愤怒”与“患动脉粥样硬化的风险”之间的关系，论据说的是“愤怒”与“血管舒张能力受损”之间的关系，二者话题不一致，且提问方式为“前提”，加强优先考虑搭桥，即在“血管舒张能力受损”与“患动脉粥样硬化的风险”之间建立联系。<br>第二步：逐一分析选项。<br>A项：指出血管舒张能力受损引发血管内壁功能的显著变化，但不明确是否会增加患动脉粥样硬化的风险，不明确选项，无法加强，排除；<br>B项：指出回忆愤怒经历与心血管疾病之间存在关联，但不明确是否会增加患动脉粥样硬化的风险，不明确选项，无法加强，排除；<br>C项：指出血管舒张能力受损会增加患动脉粥样硬化的风险，在“血管舒张能力受损”与“患动脉粥样硬化的风险”之间建立了联系，搭桥选项，是论证成立的前提，当选；<br>D项：指出实验前受试者都未检出血管舒张能力受损，说明实验具有科学性，但论点讨论的是患动脉粥样硬化的风险，所以不是论证成立的前提，排除。<br>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":89,"pid":"p25bd314b90"},{"qid":"13504365","no":32,"type":"逻辑判断","module":"判断推理","stem":"<p>金鹃是具有巢寄生习性的一种鸟类，它们不会自己筑巢孵卵，而是把蛋产在其他种类鸟类（寄主）的巢中，由寄主代孵和育雏，但金鹃雏鸟一旦孵出，会将寄主的蛋从巢中清除出去。在研究金鹃与其非巢寄生的近亲物种后发现，金鹃在基因上分化的速度更快，形成了更多的物种群类。可见，巢寄生有助于促进具有这一习性鸟类的多样性。<br>以下哪项如果为真，最能支持上述结论？</p>","options":[{"k":"A","t":"与金鹃相比，金鹃的近亲鸟类物种大多进化缓慢，对环境的适应力较弱"},{"k":"B","t":"寄主的雏鸟比金鹃的雏鸟出壳晚，金鹃雏鸟破壳后便本能地将寄主的蛋拱出巢外"},{"k":"C","t":"在金鹃产蛋的过程中，某些寄主鸟类无法有效应对金鹃的巢寄生行为，数量出现锐减"},{"k":"D","t":"金鹃雏鸟影响寄主自身的繁殖，为此寄主要识别并排除金鹃，促使金鹃不断进化出与寄主雏鸟更接近的能力"}],"answer":"D","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：巢寄生有助于促进具有这一习性鸟类的多样性。<br>论据：在研究金鹃与其非巢寄生的近亲物种后发现，金鹃在基因上分化的速度更快，形成了更多的物种群类。<br>本题论点和论据都在讨论“巢寄生有助于这一习性鸟类的多样性”，二者话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：指出金鹃的近亲鸟类物种大多进化缓慢，但未提及这些鸟类是否为巢寄生，也未明确提及这些鸟类的基因分化速度，为不明确项，无法加强，排除；<br>B项：指出金鹃雏鸟会将寄主的蛋拱出巢外，但论点讨论的是“巢寄生有助于这一习性鸟类的多样性”，话题不一致，无法加强，排除；<br>C项：指出金鹃的某些寄主因无法有效应对金鹃的巢寄生行为而数量锐减，但论点讨论的是“巢寄生有助于这一习性鸟类的多样性”，话题不一致，无法加强，排除；<br>D项：指出寄主的识别促使金鹃不断进化出与寄主雏鸟更接近的能力，解释了为什么金鹃会在基因上分化的速度变快，补充论据，可以加强，当选。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":90,"pid":"p25bd314b90"},{"qid":"13504366","no":33,"type":"逻辑判断","module":"判断推理","stem":"<p>深度睡眠阶段，人体会从大脑中移除不想要的或可能有害的物质，包括阿尔茨海默病中聚集的主要蛋白质，如Tau蛋白。阿尔茨海默病患者的一种病理变化是脑内Tau蛋白过度磷酸化，在细胞内堆积形成神经原纤维缠结。因此有研究者认为，深度睡眠不足会增加罹患阿尔茨海默病的风险。<br>以下哪项如果为真，最能削弱上述结论?</p>","options":[{"k":"A","t":"神经原纤维缠结与神经细胞死亡和认知功能障碍密切相关"},{"k":"B","t":"携带阿尔茨海默病高风险基因的人更可能出现深度睡眠不足"},{"k":"C","t":"精神刺激、创伤、神经系统疾病等因素都可诱发阿尔茨海默病"},{"k":"D","t":"年轻人的深度睡眠占睡眠时间的20%~25%，老年人只占5%~7%"}],"answer":"B","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：深度睡眠不足会增加罹患阿尔茨海默病的风险。<br>论据：深度睡眠阶段，人体会从大脑中移除不想要的或可能有害的物质，包括阿尔茨海默病中聚集的主要蛋白质，如Tau蛋白。阿尔茨海默病患者的一种病理变化是脑内Tau蛋白过度磷酸化，在细胞内堆积形成神经原纤维缠结。<br>本题论点和论据讨论的都是深度睡眠和患阿尔茨海默病的风险之间的关系，二者话题一致，优先考虑削弱论点，且论点包含因果关系，还可以考虑因果倒置或他因削弱。<br>第二步：逐一分析选项。<br>A项：该项指出神经原纤维缠结与神经细胞死亡和认知功能障碍密切相关，但是，由于认知功能障碍包含的疾病类型诸多，不一定只有阿尔茨海默病，因此选项不明确，无法削弱，排除；<br>B项：该项指出携带阿尔茨海默病高风险基因的人更可能出现深度睡眠不足，说明深度睡眠不足可能是由阿尔茨海默病的遗传风险（高风险基因）引起的，而不是深度睡眠不足导致了阿尔茨海默病，因此选项为因果倒置，可以削弱，当选；<br>C项：该项说明精神刺激、创伤、神经系统疾病等因素都可诱发阿尔茨海默病，提出了其他可能的阿尔茨海默病的风险因素，但并未说明这些因素与深度睡眠的关系，因此无法削弱深度睡眠不足和阿尔茨海默病之间的关系，话题不一致，无法削弱，排除；<br>D项：该项指出年轻人和老年人深度睡眠在睡眠时间中的占比，说明深度睡眠的比例随着年龄的增长而减少，但它并没有说明年轻人和老年人中患阿尔茨海默病的占比，因此无法直接削弱深度睡眠不足和阿尔茨海默病之间的关系，话题不一致，无法削弱，排除。<br>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":91,"pid":"p25bd314b90"},{"qid":"13504393","no":34,"type":"逻辑判断","module":"判断推理","stem":"<p>一项有关办公模式的研究中，研究机构选择了全球最大在线旅行社之一的M公司员工进行了实验，该公司员工约有1600人，研究发现，与每天到办公室工作相比，每周居家办公两天的混合办公模式不仅没有影响员工的工作表现，还能有效降低人力成本。因此，研究机构认为：混合办公模式是公司运营的有效模式。<br>以下哪项如果为真，最能支持上述结论？</p>","options":[{"k":"A","t":"M公司推行混合办公模式后，员工辞职率下降了33%"},{"k":"B","t":"M公司中，采用混合办公模式人员和非混合办公模式人员在晋升方面机会均等"},{"k":"C","t":"近几年来全球约1亿员工采用混合工作制，M公司所在国有很多企业都赞成该模式"},{"k":"D","t":"如果员工每周5天不在办公室工作，员工培训指导以及公司文化都会受到较大影响"}],"answer":"A","multi":false,"explanation":"<p>第一步：找出论点和论据。<br>论点：混合办公模式是公司运营的有效模式。<br>论据：一项对M公司员工约1600人进行的实验发现，与每天到办公室工作相比，每周居家办公两天的混合办公模式不仅没有影响员工的工作表现，还能有效降低人力成本。<br>本题论据说的是混合办公模式的一些优势，论点说的是混合办公模式是公司运营的有效模式，二者话题一致，加强优先考虑补充论据。<br>第二步：逐一分析选项。<br>A项：该项说的是混合办公模式降低了M公司的辞职率，提升了员工的稳定性，有利于公司运营，补充论据，可以加强，当选；<br>B项：该项说的是混合办公模式对“人员晋升”的影响，不涉及公司运营，话题不一致，无法加强，排除；<br>C项：该项说的是混合办公模式的使用情况和其他企业的态度，不涉及公司运营，话题不一致，无法加强，排除；<br>D项：该项说的是混合办公模式产生的负面影响，不利于公司运营，具有削弱作用，排除。<br>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":92,"pid":"p25bd314b90"},{"qid":"13504380","no":35,"type":"逻辑判断","module":"判断推理","stem":"<p>某公司举办年会，所有表演街舞的员工都表演了民族舞，所有表演民族舞的员工都表演了唱歌，有些表演吉他演奏的员工表演了诗朗诵，所有表演吉他演奏的员工都没有表演唱歌。<br>根据上述陈述，不能推出以下哪项？</p>","options":[{"k":"A","t":"所有表演街舞的员工都表演了唱歌"},{"k":"B","t":"有些表演街舞的员工表演了吉他演奏"},{"k":"C","t":"有的表演诗朗诵的员工没有表演唱歌"},{"k":"D","t":"所有表演吉他演奏的员工都没有表演民族舞"}],"answer":"B","multi":false,"explanation":"<p>第一步：翻译题干。</p><p>①表演街舞<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演民族舞；</p><p>②表演民族舞<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演唱歌；</p><p>③有的表演吉他演奏<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演诗朗诵；</p><p>④表演吉他演奏<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演唱歌；</p><p>条件③可换位为：⑤有的表演诗朗诵<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演吉他演奏；</p><p>可将条件①②逆否后和条件④⑤串联推出：⑥有的表演诗朗诵<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演吉他演奏<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演唱歌<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演民族舞<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演街舞。</p><p>第二步：逐一分析选项。</p><p>A项：翻译为表演街舞<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演唱歌，“表演街舞”是对条件⑥的否后，否后必否前，可以推出，排除；</p><p>B项：翻译为有的表演街舞<img src=\"assets/img/gongshi/formula-220d6005ff946aad.png\" class=\"tex\">表演吉他演奏，根据条件⑥可知，表演吉他演奏<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演街舞，将其逆否后为，表演街舞<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演吉他演奏，“所有A不是B”与“有的A是B”互为矛盾关系，无法推出，当选；</p><p>C项：翻译为有的表演诗朗诵<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演唱歌，根据条件⑥可以推出，排除；</p><p>D项：翻译为表演吉他演奏<img src=\"assets/img/gongshi/formula-692b70564d8c5bce.png\" class=\"tex\">表演民族舞，“表演吉他演奏”是对条件⑥的肯前，肯前必肯后，可以推出，排除。</p><p>本题为选非题，故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"判断推理"},"idx":93,"pid":"p25bd314b90"},{"qid":"13504270","no":1,"type":"综合","module":"资料分析","stem":"<p>2023年全球发明专利授权量约为多少万件？</p>","material":"<p><img src=\"assets/img/timu/1959891a2945500.png\" class=\"fig\" style=\"width:590px;height:332px;\"></p><p><img src=\"assets/img/timu/19598b63782b970.png\" class=\"fig\" style=\"width:593px;height:187px;\"></p>","materialNo":1,"options":[{"k":"A","t":"200"},{"k":"B","t":"184"},{"k":"C","t":"39"},{"k":"D","t":"20"}],"answer":"A","multi":false,"explanation":"<p>根据题干“2023年全球发明专利······多少万件”，结合材料给出2023年数字经济核心产业全球发明专利授权量及占全球发明专利授权总量比重，可判定本题为现期比重问题。定位统计图可得：2023年数字经济核心产业全球发明专利授权量为88.79万件，占全球发明专利授权总量比重为44.4%。 根据公式：整体<img src=\"assets/img/gongshi/formula-e94c4ad87ea0e515.png\" class=\"tex\">，可得所求<img src=\"assets/img/gongshi/formula-e51b8b46de481416.png\" class=\"tex\">万件。</p><p>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":94,"pid":"p25bd314b90"},{"qid":"13504272","no":2,"type":"增长","module":"资料分析","stem":"<p>2017-2023年间，数字经济核心产业全球发明专利授权量同比增速不到5%的年份有几个？</p>","material":"<p><img src=\"assets/img/timu/1959891a2945500.png\" class=\"fig\" style=\"width:590px;height:332px;\"></p><p><img src=\"assets/img/timu/19598b63782b970.png\" class=\"fig\" style=\"width:593px;height:187px;\"></p>","materialNo":1,"options":[{"k":"A","t":"0"},{"k":"B","t":"1"},{"k":"C","t":"2"},{"k":"D","t":"3"}],"answer":"B","multi":false,"explanation":"<p>根据题干“2017-2023年······同比增速不到5%的年份有几个”，可判定本题为一般增长率问题。定位统计图可得2016-2023年每年数字经济核心产业全球发明专利授权量。根据公式：增长率<img src=\"assets/img/gongshi/formula-9ad7a88fa1bfefd7.png\" class=\"tex\">，则2017-2023年，每年数字经济核心产业全球发明专利授权量的同比增速分别为：</p><p>2017年：<img src=\"assets/img/gongshi/formula-41ba33470d7aa9ec.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-702aa0c154473d04.png\" class=\"tex\">，不符合；</p><p>2018年：<img src=\"assets/img/gongshi/formula-72c0bc6374e8615c.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-ed57e15f0b02dc47.png\" class=\"tex\">，符合；</p><p>2019年：<img src=\"assets/img/gongshi/formula-a654985112f4c92a.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-d5e8180f1961980e.png\" class=\"tex\">，不符合；</p><p>2020年：<img src=\"assets/img/gongshi/formula-44e7ade3c002091c.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-e4fc1e821ebe0d11.png\" class=\"tex\">，不符合；</p><p>2021年：<img src=\"assets/img/gongshi/formula-6c8ed021c511983a.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-5c58d9ffdb92c076.png\" class=\"tex\">，不符合；</p><p>2022年：<img src=\"assets/img/gongshi/formula-cb8a8dcefc3093ec.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-11325176ca52440a.png\" class=\"tex\">，不符合；</p><p>2023年：<img src=\"assets/img/gongshi/formula-96a1e4f9f5be8413.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-02efa8c2bf8aee68.png\" class=\"tex\">，不符合。</p><p>综上，2017-2023年间，数字经济核心产业全球发明专利授权量同比增速不到5%的年份有2018年，共1个。</p><p>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":95,"pid":"p25bd314b90"},{"qid":"13504274","no":3,"type":"比重","module":"资料分析","stem":"<p>2023年数字产品制造业全球发明专利授权量占该年全球发明专利授权量的比重约为：</p>","material":"<p><img src=\"assets/img/timu/1959891a2945500.png\" class=\"fig\" style=\"width:590px;height:332px;\"></p><p><img src=\"assets/img/timu/19598b63782b970.png\" class=\"fig\" style=\"width:593px;height:187px;\"></p>","materialNo":1,"options":[{"k":"A","t":"51.2%"},{"k":"B","t":"44.4%"},{"k":"C","t":"31.6%"},{"k":"D","t":"22.7%"}],"answer":"D","multi":false,"explanation":"<p>根据题干“2023年······占该年······的比重约为”，结合材料时间为2023年，可判定本题为现期比重问题。定位统计图可知：2023年数字经济核心产业全球发明专利授权量为88.79万件，占全球发明专利授权总量比重为44.4%；定位统计表可知：2023年数字产品制造业全球发明专利授权量为454221件。根据公式：比重<img src=\"assets/img/gongshi/formula-d63da1f151f9c3a5.png\" class=\"tex\">，可得题干所求比重为<img src=\"assets/img/gongshi/formula-57a77195d8dfe975.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-b05db3f98c933062.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-0025ae4d43c084ce.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-8d6d3cc7f64f6478.png\" class=\"tex\">，与D项最接近。</p><p>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":96,"pid":"p25bd314b90"},{"qid":"13504407","no":4,"type":"综合","module":"资料分析","stem":"<p>2022年，数字要素驱动业全球发明专利授权量约比数字技术应用业全球发明专利授权量多多少万件？</p>","material":"<p><img src=\"assets/img/timu/1959891a2945500.png\" class=\"fig\" style=\"width:590px;height:332px;\"></p><p><img src=\"assets/img/timu/19598b63782b970.png\" class=\"fig\" style=\"width:593px;height:187px;\"></p>","materialNo":1,"options":[{"k":"A","t":"21.7"},{"k":"B","t":"19.5"},{"k":"C","t":"8.4"},{"k":"D","t":"6.1"}],"answer":"D","multi":false,"explanation":"<p>根据题干“2022年······比······多多少万件”，结合材料时间为2023年，可判定本题为基期和差问题。定位表格材料可得：2023年数字要素驱动业全球发明专利授权量为258489件，同比增长21.5%；数字技术应用业全球发明专利授权量为174852件，同比增长15.1%。根据公式：基期量<img src=\"assets/img/gongshi/formula-0136d9c7a25c249d.png\" class=\"tex\">，则所求为<img src=\"assets/img/gongshi/formula-b03e4a5198a441aa.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-c06341ddf58b4610.png\" class=\"tex\">万件，与D项最接近。</p><p>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":97,"pid":"p25bd314b90"},{"qid":"13504277","no":5,"type":"增长","module":"资料分析","stem":"<p>以下折线图反映了哪一时间段内，数字经济核心产业全球发明专利授权量同比增速的变化趋势？</p><p><img src=\"assets/img/timu/19598a32a1329ef.png\" class=\"fig\" style=\"width:240px;height:140px;\"></p>","material":"<p><img src=\"assets/img/timu/1959891a2945500.png\" class=\"fig\" style=\"width:590px;height:332px;\"></p><p><img src=\"assets/img/timu/19598b63782b970.png\" class=\"fig\" style=\"width:593px;height:187px;\"></p>","materialNo":1,"options":[{"k":"A","t":"2016-2018年"},{"k":"B","t":"2017-2019年"},{"k":"C","t":"2018-2020年"},{"k":"D","t":"2020-2022年"}],"answer":"B","multi":false,"explanation":"<p>根据题干“······同比增速的变化趋势”，可判定本题为一般增长率问题。定位统计图可知2016-2022年数字经济核心产业全球发明专利授权量。由于材料未给出2015年相关数据，故2016年数字经济核心产业全球发明专利授权量同比增速无法计算，排除A项。根据公式：<img src=\"assets/img/gongshi/formula-cbd7f8be3f7311cb.png\" class=\"tex\">，则2017-2022年数字经济核心产业全球发明专利授权量同比增速分别为：</p><p>2017年：<img src=\"assets/img/gongshi/formula-506fffd7b2c1e3ec.png\" class=\"tex\">；</p><p>2018年：<img src=\"assets/img/gongshi/formula-561bb35d8548d01c.png\" class=\"tex\">；</p><p>2019年：<img src=\"assets/img/gongshi/formula-f8883bd388f70058.png\" class=\"tex\">；</p><p>2020年：<img src=\"assets/img/gongshi/formula-fbfdcce165dcc1d9.png\" class=\"tex\">；</p><p>2021年：<img src=\"assets/img/gongshi/formula-1b967a2434845b13.png\" class=\"tex\">；</p><p>2022年：<img src=\"assets/img/gongshi/formula-41de57dfc015dcfd.png\" class=\"tex\">。</p><p>观察发现，折线图先下降再上升，且第3个点高于第1个点，只有2017-2019年满足该变化趋势。</p><p>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":98,"pid":"p25bd314b90"},{"qid":"13504524","no":6,"type":"增长","module":"资料分析","stem":"<p>2020-2023年间，全国年底海水淡化工程规模同比增速最快的年份是：</p>","material":"<p>        截至2023年底，全国现有海水淡化工程156个，同比增加了6个。其中，万吨级及以上海水淡化工程55个，工程规模2300723吨/日，千吨及以上万吨级以下海水淡化工程51个，工程规模208266吨/日，千吨级以下海水淡化工程50个，全国海水淡化工程分布点10个省级行政区。</p><p><img src=\"assets/img/timu/195f5dec1f08ead.jpg\" class=\"fig\" style=\"width:700px;height:487px;\"></p>","materialNo":2,"options":[{"k":"A","t":"2020年"},{"k":"B","t":"2021年"},{"k":"C","t":"2022年"},{"k":"D","t":"2023年"}],"answer":"C","multi":false,"explanation":"<p>根据题干“······同比增速最快的年份是”，可判定本题为一般增长率问题。定位统计图可知2019-2023年每年全国年底海水淡化工程规模。根据公式：增长率<img src=\"assets/img/gongshi/formula-9ad7a88fa1bfefd7.png\" class=\"tex\">，可得2020-2023年间，全国年底海水淡化工程规模同比增速依次为：</p><p>2020年<img src=\"assets/img/gongshi/formula-1b101018fca08e10.png\" class=\"tex\">；</p><p>2021年<img src=\"assets/img/gongshi/formula-41b928458601c3b0.png\" class=\"tex\">；</p><p>2022年<img src=\"assets/img/gongshi/formula-9076f4f1e7ba7dfa.png\" class=\"tex\">；</p><p>2023年<img src=\"assets/img/gongshi/formula-4984a5bedb3c248a.png\" class=\"tex\">。</p><p>比较可得，2022年同比增速最快。</p><p>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":99,"pid":"p25bd314b90"},{"qid":"13504525","no":7,"type":"平均数","module":"资料分析","stem":"<p>2022年底，我国平均每个海水淡化工程规模约在以下哪个范围内？</p>","material":"<p>        截至2023年底，全国现有海水淡化工程156个，同比增加了6个。其中，万吨级及以上海水淡化工程55个，工程规模2300723吨/日，千吨及以上万吨级以下海水淡化工程51个，工程规模208266吨/日，千吨级以下海水淡化工程50个，全国海水淡化工程分布点10个省级行政区。</p><p><img src=\"assets/img/timu/195f5dec1f08ead.jpg\" class=\"fig\" style=\"width:700px;height:487px;\"></p>","materialNo":2,"options":[{"k":"A","t":"不到1.5万吨/日"},{"k":"B","t":"1.5-1.6万吨/日之间"},{"k":"C","t":"1.6-1.7万吨/日之间"},{"k":"D","t":"超过1.7万吨/日"}],"answer":"B","multi":false,"explanation":"<p>根据题干“2022年底······平均每个·····”，结合材料时间为2023年，可判定本题为基期平均数问题。定位文字材料可得，2023年底全国现有海水淡化工程156个，同比增加了6个；定位统计图可得，2022年底全国海水淡化工程规模为2357048吨/日。则所求平均数<img src=\"assets/img/gongshi/formula-114e4b2ecb0f2b03.png\" class=\"tex\">吨/日=1.57万吨/日，在B项范围内。</p><p>故正确答案为B。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":100,"pid":"p25bd314b90"},{"qid":"12882043","no":8,"type":"平均数","module":"资料分析","stem":"<p>2023年底，我国平均每个千吨级以下海水淡化工程规模约为多少吨/日？</p>","material":"<p>        截至2023年底，全国现有海水淡化工程156个，同比增加了6个。其中，万吨级及以上海水淡化工程55个，工程规模2300723吨/日，千吨及以上万吨级以下海水淡化工程51个，工程规模208266吨/日，千吨级以下海水淡化工程50个，全国海水淡化工程分布点10个省级行政区。</p><p><img src=\"assets/img/timu/195f5dec1f08ead.jpg\" class=\"fig\" style=\"width:700px;height:487px;\"></p>","materialNo":2,"options":[{"k":"A","t":"279"},{"k":"B","t":"285"},{"k":"C","t":"296"},{"k":"D","t":"324"}],"answer":"A","multi":false,"explanation":"<p>根据题干“2023年底······平均每个······”，结合材料时间为2023年底，可判定本题为现期平均数问题。定位文字材料可得：截至2023年底，全国万吨级及以上海水淡化工程规模为2300723吨每日，千吨及以上万吨级以下海水淡化工程规模为208266吨/日，千吨级以下海水淡化工程50个；定位统计图可得：2023年底全国海水淡化工程规模为2522956吨/日。2023年底，千吨级以下海水淡化工程规模=全国海水淡化工程规模-万吨级及以上海水淡化工程规模-千吨及以上万吨级以下海水淡化工程规模=2522956-2300723-208266=13967吨/日，则所求平均数<img src=\"assets/img/gongshi/formula-63f19e2d698a6e78.png\" class=\"tex\">吨/日。</p><p>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":101,"pid":"p25bd314b90"},{"qid":"13504526","no":9,"type":"比重","module":"资料分析","stem":"<p>以下饼图中，最能准确反应2023年底浙江（黑色），山东（灰色）和其他省级行政区（白色）海水淡化工程规模占全国比重的是：</p>","material":"<p>        截至2023年底，全国现有海水淡化工程156个，同比增加了6个。其中，万吨级及以上海水淡化工程55个，工程规模2300723吨/日，千吨及以上万吨级以下海水淡化工程51个，工程规模208266吨/日，千吨级以下海水淡化工程50个，全国海水淡化工程分布点10个省级行政区。</p><p><img src=\"assets/img/timu/195f5dec1f08ead.jpg\" class=\"fig\" style=\"width:700px;height:487px;\"></p>","materialNo":2,"options":[{"k":"A","t":"<p><img src=\"assets/img/timu/19599ec6bb5030e.png\" class=\"fig\" style=\"width:230px;height:230px;\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/timu/19599ec7c40c50a.png\" class=\"fig\" style=\"width:234px;height:234px;\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/timu/19599ec8b81d599.png\" class=\"fig\" style=\"width:235px;height:235px;\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/timu/19599ec99b00911.png\" class=\"fig\" style=\"width:235px;height:236px;\"></p>"}],"answer":"D","multi":false,"explanation":"<p>根据题干“以下饼图中，最能准确反应2023年底······占全国比重的是”，结合材料时间为2023年底，可判定本题为现期比重问题。定位统计图可得：2023年底全国海水淡化工程规模2522956吨/日；定位统计表可得：2023年底浙江、山东海水淡化工程规模分别为801473吨/日、713209吨/日，则<img src=\"assets/img/gongshi/formula-3649dedd3766a6a5.png\" class=\"tex\">，即黑色区域约是灰色区域的1.1倍，排除A、B两项。根据公式：比重<img src=\"assets/img/gongshi/formula-d63da1f151f9c3a5.png\" class=\"tex\">，则2023年浙江、山东海水淡化工程规模之和占全国比重<img src=\"assets/img/gongshi/formula-1306efee343d718d.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-f39b97a7e2cd39d5.png\" class=\"tex\">，即黑色区域和灰色区域占比之和超过<img src=\"assets/img/gongshi/formula-478a48f2934d67c5.png\" class=\"tex\">，排除C项。</p><p>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":102,"pid":"p25bd314b90"},{"qid":"13504528","no":10,"type":"增长","module":"资料分析","stem":"<p>以下柱状图中，最能准确反映2020~2023年间，全国年底海水淡化工程规模同比增量变化趋势的是（横轴位置代表增量为0）：</p>","material":"<p>        截至2023年底，全国现有海水淡化工程156个，同比增加了6个。其中，万吨级及以上海水淡化工程55个，工程规模2300723吨/日，千吨及以上万吨级以下海水淡化工程51个，工程规模208266吨/日，千吨级以下海水淡化工程50个，全国海水淡化工程分布点10个省级行政区。</p><p><img src=\"assets/img/timu/195f5dec1f08ead.jpg\" class=\"fig\" style=\"width:700px;height:487px;\"></p>","materialNo":2,"options":[{"k":"A","t":"<p><img src=\"assets/img/timu/1959a22fa5d3260.png\" class=\"fig\" style=\"width:306px;height:147px;\"></p>"},{"k":"B","t":"<p><img src=\"assets/img/timu/1959a248de2e754.png\" class=\"fig\" style=\"width:310px;height:167px;\"></p>"},{"k":"C","t":"<p><img src=\"assets/img/timu/1959a24bbc5e815.png\" class=\"fig\" style=\"width:321px;height:151px;\"></p>"},{"k":"D","t":"<p><img src=\"assets/img/timu/1959a24d9b8bb70.png\" class=\"fig\" style=\"width:315px;height:154px;\"></p>"}],"answer":"A","multi":false,"explanation":"<p>根据题干“······最能准确反映······同比增量变化趋势的是”，可判定本题为增长量比较问题。定位统计图可知2019-2023年每年全国年底海水淡化工程规模。根据公式：增长量=现期量-基期量，可得2020-2023年间，全国年底海水淡化工程规模同比增量依次为：</p><p>2020年<img src=\"assets/img/gongshi/formula-9c8655de336f800e.png\" class=\"tex\">吨/日；</p><p>2021年<img src=\"assets/img/gongshi/formula-798613817e44a287.png\" class=\"tex\">吨/日；</p><p>2022年<img src=\"assets/img/gongshi/formula-b050e61ebfd5b316.png\" class=\"tex\">吨/日；</p><p>2023年<img src=\"assets/img/gongshi/formula-ccadfc00737aac8f.png\" class=\"tex\">吨/日。</p><p>比较可知，2020年同比增量最小，排除C、D两项；2022年同比增量最大，排除B项。只有A项符合。</p><p>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":103,"pid":"p25bd314b90"},{"qid":"13504302","no":11,"type":"综合","module":"资料分析","stem":"<p>2024年1-6月，我国自行车出口量在以下哪个范围内？</p>","material":"<p>        2024年1-6月，T市出口自行车占同期全国自行车出口比重为33.6%，位居全国首位。其中，民营企业出口414.9万辆，同比增加27.8%；国有企业出口351.8万辆，同比增加6.9%；其他企业出口11.6万辆。对东盟、日本分别出口213.4万辆、176.6万辆，同比分别增加4.9%、5.3%；对美国出口115.3万辆，同比增加10.1%。</p><p><img src=\"assets/img/timu/195991eae8a212e.png\" class=\"fig\" style=\"width:697px;height:391px;\"></p>","materialNo":3,"options":[{"k":"A","t":"不到0.18亿辆"},{"k":"B","t":"0.18-0.20亿辆"},{"k":"C","t":"0.20-0.22亿辆"},{"k":"D","t":"0.22亿辆以上"}],"answer":"D","multi":false,"explanation":"<p>根据题干“2024年1-6月，我国自行车出口量在以下哪个范围内”，结合材料给出2024年1-6月T市自行车出口相关数据及占同期全国自行车出口比重，可判定本题为现期比重问题。定位文字材料可得：2024年1-6月，T市出口自行车占同期全国自行车出口比重为33.6%。定位统计表可得，2024年1-6月，T市自行车出口量778.3万辆。根据公式：整体<img src=\"assets/img/gongshi/formula-e94c4ad87ea0e515.png\" class=\"tex\">，则2024年1-6月我国自行车出口量<img src=\"assets/img/gongshi/formula-ec1d15b3e177dbc1.png\" class=\"tex\">万辆<img src=\"assets/img/gongshi/formula-748245e4495021d7.png\" class=\"tex\">亿辆，在D项范围内。</p><p>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":104,"pid":"p25bd314b90"},{"qid":"13504303","no":12,"type":"综合","module":"资料分析","stem":"<p>2024年1-6月T市国有企业自行车出口增量约占同期T市自行车出口增量的：</p>","material":"<p>        2024年1-6月，T市出口自行车占同期全国自行车出口比重为33.6%，位居全国首位。其中，民营企业出口414.9万辆，同比增加27.8%；国有企业出口351.8万辆，同比增加6.9%；其他企业出口11.6万辆。对东盟、日本分别出口213.4万辆、176.6万辆，同比分别增加4.9%、5.3%；对美国出口115.3万辆，同比增加10.1%。</p><p><img src=\"assets/img/timu/195991eae8a212e.png\" class=\"fig\" style=\"width:697px;height:391px;\"></p>","materialNo":3,"options":[{"k":"A","t":"58%"},{"k":"B","t":"46%"},{"k":"C","t":"32%"},{"k":"D","t":"24%"}],"answer":"D","multi":false,"explanation":"<p>根据题干“2024年1-6月······占······”，结合材料时间为2024年1-6月，可判定本题为现期比重问题。定位文字材料可得：2024年1-6月，T市国有企业自行车出口351.8万辆，同比增加6.9%。定位统计表可得：2024年1-6月，T市自行车出口778.3万辆，同比增长14.0%。根据公式：增长量<img src=\"assets/img/gongshi/formula-a5cec0422ef43b9c.png\" class=\"tex\">，比重<img src=\"assets/img/gongshi/formula-d63da1f151f9c3a5.png\" class=\"tex\">，可得2024年1-6月T市国有企业自行车出口增量为<img src=\"assets/img/gongshi/formula-506e1af946951e38.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-de0bf097e1bf43fe.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-77d4afa3ed7aa6c2.png\" class=\"tex\">万辆；T市自行车出口增量为<img src=\"assets/img/gongshi/formula-17591ec5bd38b0d7.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-d88cf803f01256dc.png\" class=\"tex\"><img src=\"assets/img/gongshi/formula-bacd94c1b3ae3b2c.png\" class=\"tex\">万辆。则所求为<img src=\"assets/img/gongshi/formula-187f84b36855eecc.png\" class=\"tex\">，与D项最接近。</p><p>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":105,"pid":"p25bd314b90"},{"qid":"13504410","no":13,"type":"增长","module":"资料分析","stem":"<p>2024年1~6月T市民营企业自行车出口量占同期T市自行车出口总量比上年同期约：</p>","material":"<p>        2024年1-6月，T市出口自行车占同期全国自行车出口比重为33.6%，位居全国首位。其中，民营企业出口414.9万辆，同比增加27.8%；国有企业出口351.8万辆，同比增加6.9%；其他企业出口11.6万辆。对东盟、日本分别出口213.4万辆、176.6万辆，同比分别增加4.9%、5.3%；对美国出口115.3万辆，同比增加10.1%。</p><p><img src=\"assets/img/timu/195991eae8a212e.png\" class=\"fig\" style=\"width:697px;height:391px;\"></p>","materialNo":3,"options":[{"k":"A","t":"提升了5.8个百分点"},{"k":"B","t":"下降了5.8个百分点"},{"k":"C","t":"提升了9.6个百分点"},{"k":"D","t":"下降了9.6个百分点"}],"answer":"A","multi":false,"explanation":"<p>根据题干“2024年1~6月······占······总量比上年同期约”，结合选项为提升了/下降了+百分点，可判定本题为两期比重问题。定位文字材料可得：2024年1-6月，T市民营企业自行车出口量为414.9万辆（A），同比增加27.8%（a）。定位表格材料可得：2024年1-6月，T市自行车出口总量为778.3万辆（B），同比增长14.0%（b）。根据公式：两期比重差<img src=\"assets/img/gongshi/formula-92c7088e8e409434.png\" class=\"tex\">，则所求比重差为<img src=\"assets/img/gongshi/formula-b4170009b1713fee.png\" class=\"tex\">，即提升了约5.74个百分点，与A项最接近。</p><p>故正确答案为A。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":106,"pid":"p25bd314b90"},{"qid":"13504305","no":14,"type":"增长","module":"资料分析","stem":"<p>2024年1-6月，T市自行车出口均价同比下降的月份有几个？</p>","material":"<p>        2024年1-6月，T市出口自行车占同期全国自行车出口比重为33.6%，位居全国首位。其中，民营企业出口414.9万辆，同比增加27.8%；国有企业出口351.8万辆，同比增加6.9%；其他企业出口11.6万辆。对东盟、日本分别出口213.4万辆、176.6万辆，同比分别增加4.9%、5.3%；对美国出口115.3万辆，同比增加10.1%。</p><p><img src=\"assets/img/timu/195991eae8a212e.png\" class=\"fig\" style=\"width:697px;height:391px;\"></p>","materialNo":3,"options":[{"k":"A","t":"3"},{"k":"B","t":"4"},{"k":"C","t":"5"},{"k":"D","t":"6"}],"answer":"C","multi":false,"explanation":"<p>根据题干“2024年1-6月······出口均价同比下降的月份有几个”，结合公式：出口均价<img src=\"assets/img/gongshi/formula-12bcb71e8fd49af6.png\" class=\"tex\">，可判定本题为两期平均数比较问题。定位统计表可得2024年1-6月T市自行车出口金额、出口数量及同比增长率。根据两期平均数比较结论，当分子增长率（a）&lt;分母增长率（b）时，平均数下降。观察表格，满足a&lt;b的有：1月（24.9%&lt;34.7%），3月（-5.5%&lt;-0.4%），4月（3.1%&lt;9.6%），5月（-5.0%&lt;9.8%），6月（2.9%&lt;9.5%），共5个月份。</p><p>故正确答案为C。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":107,"pid":"p25bd314b90"},{"qid":"13504306","no":15,"type":"综合","module":"资料分析","stem":"<p>以下柱状图反映了2024年哪一时间段内，T市自行车出口哪一指标环比增量变化情况？（横轴位置代表增量为0）</p><p><img src=\"assets/img/timu/195992015506ac6.png\" class=\"fig\" style=\"width:542px;height:287px;\"></p>","material":"<p>        2024年1-6月，T市出口自行车占同期全国自行车出口比重为33.6%，位居全国首位。其中，民营企业出口414.9万辆，同比增加27.8%；国有企业出口351.8万辆，同比增加6.9%；其他企业出口11.6万辆。对东盟、日本分别出口213.4万辆、176.6万辆，同比分别增加4.9%、5.3%；对美国出口115.3万辆，同比增加10.1%。</p><p><img src=\"assets/img/timu/195991eae8a212e.png\" class=\"fig\" style=\"width:697px;height:391px;\"></p>","materialNo":3,"options":[{"k":"A","t":"2-5月出口量"},{"k":"B","t":"3-6月出口量"},{"k":"C","t":"2-5月出口额"},{"k":"D","t":"3-6月出口额"}],"answer":"D","multi":false,"explanation":"<p>根据题干“······环比增量变化情况······”，可判定本题为增长量比较问题。定位统计表，可知2024年1-6月各月T市自行车出口量和出口额。根据公式：增长量=现期量-基期量，可得选项中各指标环比增长量如下：<br>A项，2-5月出口量：4月，136.1-126.9＞0，而柱状图2024年4月出口量的环比增长量&lt;0，不符合柱状图变化趋势，排除；<br>B项，3-6月出口量：3月，126.9-107.6=19.3万辆；4月，136.1-126.9=9.2万辆，可知2024年3月出口量环比增量&gt;2024年4月出口量环比增量，不符合柱状图变化趋势，排除；<br>C项，2-5月出口额：4月，5.2-5.0&gt;0，而柱状图2024年4月出口额的环比增长量&lt;0，不符合柱状图变化趋势，排除；<br>D项，3-6月出口额：3月，5.0-4.9=0.1亿元；4月，5.2-5.0=0.2亿元；5月，4.3-5.2=-0.9亿元；6月，4.7-4.3=0.4亿元。符合柱状图变化趋势，当选。<br>故正确答案为D。</p>","from":{"file":"2025年云南省公务员录用考试《行测》题（网友回忆版）.md","module":"资料分析"},"idx":108,"pid":"p25bd314b90"}]};
